-- أنظمةُ أدِيب ٠٢: النسخةُ الأولى من النصوص المُقَرّة
--
-- طُبِّق ٢٠٢٦-١٠-١٣ بعد `regulations_01_schema`، والنصوصُ في القاعدة مطابقةٌ له بالبصمة.
-- مُولَّدٌ بـ `node scripts/regulations-build.mjs --seed` من v2/الأنظمة/، فلا يُحرَّر باليد.
--
-- أُقرّ الدستورُ في ٢٠٢٦-١٠-١٠، وأقرّ الرئيسان الأنظمةَ الستّة بعد عرضها على المجلس الإداري
-- في ٢٠٢٦-١٠-١٢. وكلٌّ «يسري من تاريخ نشره في «أنظمة أدِيب»»، فتدخل هنا مسودّاتٍ، ويُنشرها
-- `regulations_03_publish_v1.sql` يومَ تُفتح الصفحةُ العلنيّة، فيكون تاريخُ النفاذ يومَ النشر حقًّا.
--
--   constitution  70 مادّةً في 11 بابًا
--   membership    33 مادّةً في 8 أبواب
--   positions     25 مادّةً في 6 أبواب
--   elections     33 مادّةً في 6 أبواب
--   discipline    25 مادّةً في 5 أبواب
--   volunteering  28 مادّةً في 6 أبواب
--   certificates  22 مادّةً في 5 أبواب

begin;

insert into public.regulations (slug, title, summary, position) values
  ('constitution', 'دستور أدِيب', 'اللائحةُ العليا للنادي: تعريفُه وهيكلُه ومناصبُه، وحقوقُ أعضائه وواجباتُهم، وإليها يُحيل كلُّ نظام.', 0),
  ('membership', 'نظام العضوية', 'الانضمامُ إلى أدِيب، وسجلُّ العضوية، والخروجُ منها وإنهاؤها، واستعادتُها.', 1),
  ('positions', 'نظام المناصب والصلاحيات', 'مَن يشغل كلَّ منصبٍ وكيف يتركه، والتكليفُ والتجميد، وما يملكه كلُّ منصبٍ في المنصّة.', 2),
  ('elections', 'نظام الانتخابات', 'فتحُ الانتخاب، والترشّحُ والتصويت، والفوزُ والتعثّر، والتظلّمُ فيه.', 3),
  ('discipline', 'نظام الانضباط', 'الإنذارُ وحدُّه وإلغاؤه، والتظلّمُ من كلّ قرارٍ يصدر بحقّ شخصٍ بعينه.', 4),
  ('volunteering', 'نظام التطوّع', 'صفةُ المتطوّع، وفرصُ التطوّع والتقديمُ إليها، والحضورُ والساعات، وسجلُّ المتطوّعين.', 5),
  ('certificates', 'نظام الشهادات', 'شهادتا الخبرة والمشاركة: إصدارُهما ومضمونُهما، ورقمُهما والتحقّقُ منهما، وإبطالُهما.', 6)
on conflict (slug) do nothing;

-- دستور أدِيب
insert into public.regulation_versions
  (regulation_id, version_no, status, effective_from, change_note, approval_note, body)
select r.id, 1, 'draft', null, 'الإصدار الأوّل', 'الإصدار الأول، أُقرّ في ١٠ أكتوبر ٢٠٢٦، ويسري من تاريخ نشره في «أنظمة أدِيب».',
  $body$[{"title":"الباب الأول: التعريف","articles":[{"no":1,"title":"النادي","blocks":[{"kind":"para","text":"نادي أدِيب نادٍ طلّابي ثقافي إبداعي في جامعة الملك فيصل بالأحساء. ويتبع عمادة شؤون الطلّاب."}]},{"no":2,"title":"الرسالة","blocks":[{"kind":"para","text":"نادي أدِيب هو منارة ثقافية في جامعة الملك فيصل، نسعى فيها إلى صقل المواهب ونشر الثقافة. إنها محراب لكل من يرى في الحرف روحه، والإبداع مأوى ومتنفّسًا له في شتّى المجالات الإبداعية."}]},{"no":3,"title":"الدستور","blocks":[{"kind":"para","text":"هذا الدستور اسمه «دستور أدِيب»، وهو اللائحة العليا للنادي. وكل نظام في النادي يُحيل إليه ولا يخالفه."}]}]},{"title":"الباب الثاني: المنازل","articles":[{"no":4,"title":"المنازل الثلاث","blocks":[{"kind":"para","text":"لكل صاحب حساب في أدِيب منزلة واحدة من ثلاث: عضو أدِيب، أو متطوّع أدِيب، أو صديق أدِيب. ولا تجتمع لشخص منزلتان. وحساب النادي المؤسّسي خارج المنازل."}]},{"no":5,"title":"عضو أدِيب","blocks":[{"kind":"para","text":"من له عضوية سارية، من عضو اللجنة إلى رئيس أدِيب. والمنصب رتبة داخل العضوية لا منزلة مستقلّة، ولا عضوية سارية بلا منصب أصيل."}]},{"no":6,"title":"متطوّع أدِيب","blocks":[{"kind":"para","text":"من له تطوّع قائم وليست له عضوية، طامحًا إلى العضوية أو مريدًا للتطوّع وحده. وتثبت له الصفة بتقدّمه إلى التطوّع وترتيبه رغباته."}]},{"no":7,"title":"صديق أدِيب","blocks":[{"kind":"para","text":"كل صاحب حساب ليست له عضوية سارية ولا تطوّع قائم. ومن انتهت عضويته صار صديقًا لأدِيب أيًّا كان السبب، إلا من نُقل إلى المتطوّعين."}]},{"no":8,"title":"التأنيث","blocks":[{"kind":"para","text":"يُقال للمرأة «متطوّعة أدِيب» و«صديقة أدِيب»، ويؤنَّث لها اسم المنصب: «الرئيسة التنفيذية»، و«قائدة»، و«نائبة»، و«منسّقة». ويُقال «عضو» للرجل والمرأة، في المنزلة وفي المنصب."}]},{"no":9,"title":"الطريق إلى العضوية","blocks":[{"kind":"para","text":"لا طريق إلى العضوية ابتداءً إلا التطوّع ثم إهداء العضوية (المادة ٣٧). ومن انتهت عضويته لا يعود إلا بإهداء جديد، أو باستعادة عضويته (المادة ٤٣). وللعضو السابق أن يتطوّع على ما في المادة ٦٠. والعضوية لا تُقصر على فئة: فهي لطلّاب المدارس والجامعات، والموظّفين وغيرهم، ولا تنتهي بتخرّج ولا بترك دراسة أو عمل."}]}]},{"title":"الباب الثالث: الهيكل","articles":[{"no":10,"title":"رأس الهيكل","blocks":[{"kind":"para","text":"رئيس أدِيب على رأس النادي، ويليه الرئيس التنفيذي. ويُراد بـ«الرئيسين» في هذا الدستور رئيس أدِيب والرئيس التنفيذي، يملك كلٌّ منهما منفردًا ما نُسب إليهما، إلا حيث يقول النصّ «معًا». والهيكل للأعضاء وحدهم، فلا يُسند منصب إلا لعضو، إلا منصب عضو اللجنة يُسند للمتطوّع بالإهداء (المادة ٣٧)، والمنصب الأصيل الذي تُستعاد به العضوية (المادة ٤٣)."}]},{"no":11,"title":"المجلسان","blocks":[{"kind":"para","text":"للنادي مجلسان: المجلس الإداري، والمجلس التشغيلي. يرأس كلًّا منهما منصب لا شخص بعينه."}]},{"no":12,"title":"المجلس الإداري","blocks":[{"kind":"para","text":"يرأسه رئيس أدِيب، وأعضاؤه: الرئيس التنفيذي، وقادة الإدارات الثلاث. والرئيس التنفيذي يقود الإدارة التنفيذية بمقعده، فلا يُضاف له مقعد ثانٍ. وأعضاء الإدارات تابعون للمجلس لا أعضاء فيه. وهو الجهة الإشرافية العليا في النادي: يرسم السياسات، ويراجع الأداء، ويتّخذ القرارات الكبرى. والمجلس الإداري مكان القرار، يقرّر بأغلبية أعضائه، لكلٍّ منهم صوت واحد، وإذا تعادلت الأصوات رجح صوت رئيس أدِيب."}]},{"no":13,"title":"المجلس التشغيلي","blocks":[{"kind":"para","text":"يرأسه الرئيس التنفيذي، ويضمّ الأقسام واللجان: منسّقي الأقسام، وقادة اللجان، ونوّابهم، وأعضاء اللجان. ويتولّى تنفيذ الخطط والبرامج الموافق عليها. ويتّخذ قراراته الرئيس التنفيذي بعد مشورة المجلس."}]},{"no":14,"title":"الإدارات الثلاث","blocks":[{"kind":"para","text":"تتبع الرئيسَ التنفيذي ثلاث إدارات: إدارة الموارد البشرية، وإدارة الضمان والجودة، والإدارة التنفيذية. لكلٍّ منها قائد وأعضاء، ويقود الرئيس التنفيذي الإدارة التنفيذية بنفسه ما لم يُعيَّن لها قائد. ويُراد بـ«قائدَي الإدارتين» في هذا الدستور قائدا إدارة الموارد البشرية وإدارة الضمان والجودة. وقائد الإدارة التنفيذية، إن عُيّن، يعيّنه الرئيس التنفيذي ويعزله، ويكون عضوًا في المجلس الإداري. ويرجع قادة الإدارات إلى الرئيس التنفيذي في عملهم اليومي، ويقرّرون في المجلس الإداري."}]},{"no":15,"title":"إدارة الموارد البشرية","blocks":[{"kind":"para","text":"تتولّى شؤون الأعضاء والمتطوّعين: استقطابهم، والتطوّع، والانضباط، والانتخابات، والشهادات. ولقائدها تعيين منسّقي الأقسام وقادة اللجان ونوّابهم وعزلهم. ولا يكون التعيين فيها إلا إذا تعثّر انتخابها (المادة ٢١)."}]},{"no":16,"title":"إدارة الضمان والجودة","blocks":[{"kind":"para","text":"تُعنى بمتابعة مستوى الأداء والالتزام بالمعايير المعتمدة في أنشطة النادي، وقياس جودة المخرجات، والتحسين المستمرّ. وهي إدارة رقابة لا جزاء: لا يُنذر قائدها ولا أعضاؤها أحدًا، ولا يُنهون عضوية أحد، ولا يملك قائدها من التعيين إلا تعيين أعضاء إدارته. وتتبع الرئيس التنفيذي إداريًّا، وتُعرض تقاريرها في المجلس الإداري."}]},{"no":17,"title":"الإدارة التنفيذية","blocks":[{"kind":"para","text":"ذراع الرئيس التنفيذي في أعماله: تتولّى المتابعة والتنسيق والإعداد لما يكلّفها به. ولا تشرف على اللجان، وخطّها إلى الأقسام واللجان منسّقوها. ولا سلطة لأعضائها على الأشخاص. وسلطة عضوها في كل مهمّة ما يفوّضه فيها الرئيس التنفيذي، في غير السلطة على الأشخاص."}]},{"no":18,"title":"الأقسام واللجان","blocks":[{"kind":"para","text":"تتبع الأقسام واللجان الإدارة التنفيذية عن طريق منسّقيها. لكل قسم منسّق واحد وتتبعه لجان، ولكل لجنة قائد واحد ونائب واحد وأعضاء. ويُنشئ الرئيسان معًا الأقسامَ واللجانَ ويلغيانها، ولا تُنشأ إدارة ولا تُلغى إلا بتعديل هذا الدستور (المادة ٦٨)."}]},{"no":19,"title":"الإشراف","blocks":[{"kind":"para","text":"يشرف أعضاء إدارتي الموارد البشرية والضمان والجودة على لجان المجلس التشغيلي، ولا يشرف على اللجنة الواحدة أكثر من عضو من كل إدارة. ولا يشرف أعضاء الإدارة التنفيذية. ويوزّع الإشراف ويسحبه قائد كل إدارة بين أعضاء إدارته، ويملك ذلك الرئيسان في الإدارتين كلتيهما."},{"kind":"figure","ref":"structure","caption":"هيكل أدِيب: مجلسان وثلاث إدارات"},{"kind":"para","text":"المجلس الإداري فوق، والإدارات الثلاث تتبع الرئيس التنفيذي، ويتبعها أعضاؤها الإداريون من غير أن يكونوا من أعضاء المجلس. والمجلس التشغيلي تحته، يتبع الإدارة التنفيذية، وتُشغل مقاعده بالانتخاب، وبالتعيين إن تعثّر، وبالإهداء."}]}]},{"title":"الباب الرابع: المناصب","articles":[{"no":20,"title":"المناصب","blocks":[{"kind":"para","text":"مناصب أدِيب أحد عشر: رئيس أدِيب، والرئيس التنفيذي، وقائد إدارة الموارد البشرية، وقائد إدارة الضمان والجودة، وعضو إدارة الموارد البشرية، وعضو إدارة الضمان والجودة، وعضو الإدارة التنفيذية، ومنسّق القسم، وقائد اللجنة، ونائب قائد اللجنة، وعضو اللجنة. ويُضاف إليها منصب قائد الإدارة التنفيذية إن عُيّن (المادة ١٤)، وله ما لقائدَي الإدارتين في التصويت والإعفاء من الإنذار (المادتان ٤٦ و٥٦)."}]},{"no":21,"title":"شغل المناصب","blocks":[{"kind":"para","text":"يُشغل كل منصب على ما في هذا الجدول:"},{"kind":"table","head":["المنصب","يُشغل بـ"],"rows":[["رئيس أدِيب","يسمّيه من أعضاء أدِيب رئيسُ أدِيب الذي يسبقه، فإن لم يسمِّ أحدًا صار الرئيس التنفيذي رئيسًا (المادة ٢٨)"],["الرئيس التنفيذي","تعيين من رئيس أدِيب"],["قائدا الإدارتين","تعيين من الرئيسين معًا"],["عضو الموارد البشرية، وعضو الضمان والجودة","تعيين من قائد إدارته، أو من أحد الرئيسين"],["عضو الإدارة التنفيذية","تعيين من الرئيس التنفيذي، أو من رئيس أدِيب"],["قائد الإدارة التنفيذية (إن عُيّن)","تعيين من الرئيس التنفيذي (المادة ١٤)"],["منسّق القسم، وقائد اللجنة، ونائبه","الانتخاب وفق نظام الانتخابات، فإن تعثّر فالتعيين من قائد الموارد البشرية أو أحد الرئيسين"],["عضو اللجنة","إهداء العضوية، أو التعيين والنقل من قائد الموارد البشرية أو أحد الرئيسين"]]}]},{"no":22,"title":"شرط العضوية في الإدارات","blocks":[{"kind":"para","text":"لا يُسند منصب عضو في أيٍّ من الإدارات الثلاث إلا لعضو في أدِيب، أيًّا كان منصبه، فيُنقل منه إلى الإدارة."}]},{"no":23,"title":"منصب واحد","blocks":[{"kind":"para","text":"لكل عضو منصب أصيل واحد، ويجوز أن يُضاف إليه تكليف واحد على ما في الباب الخامس. وإسناد منصب إلى من يشغل غيره نقلٌ له إليه، ولا ينقله إلا من يملك التعيين في منصبيه القديم والجديد معًا، إلا أن يكون منصبه القديم عضوية لجنة، فينقله من يملك التعيين في المنصب الجديد."}]},{"no":24,"title":"لا مدّة للمنصب","blocks":[{"kind":"para","text":"يبقى صاحب المنصب فيه حتى يتركه، أو يُعزل منه، أو تنتهي عضويته. ويسري ذلك على رئيس أدِيب، إلا أنه لا يُعزل ولا تُنهى عضويته (المادة ٢٨). ومن أراد ترك منصبه، غير عضوية اللجنة، والبقاء عضوًا طلب إعفاءه ممّن يملك عزله منه. ولا نيابة عن صاحب منصب غائب غير رئيس أدِيب، فإن طال غيابه أعفاه منه من يملك عزله، ثم يُشغل المنصب أو يُكلَّف فيه. ويعود المُعفى إلى ما يعود إليه المعزول من منصبه (المادة ٢٥)."}]},{"no":25,"title":"العزل","blocks":[{"kind":"para","text":"من يملك التعيين في منصب يملك العزل منه، ومنه المنصب المنتخب، إلا ما استثنته المادتان ٢٦ و٢٨، وما مُنع عزله في هذه المادة. ولا يعزل أحد نفسه. ومن عُزل عن قيادة لجنة أو نيابتها عاد عضوًا فيها، ومن عُزل عن قيادة إحدى الإدارتين عاد عضوًا فيها، ومن عُزل عن تنسيق قسم أو عن منصب الرئيس التنفيذي عاد عضوًا في آخر لجنة أو إدارة كان عضوًا فيها. ولا يُعزل عضو اللجنة، ولا من لا وحدة له يعود إليها، وإنما يُنقل إلى منصب آخر أو تُنهى عضويته. ومن عُزل عن عضوية إحدى الإدارات عاد إلى المنصب الذي نُقل منه إليها إن كان شاغرًا، وإلا عاد عضوًا في آخر لجنة كان عضوًا فيها. ومن عُزل عن قيادة الإدارة التنفيذية عاد عضوًا فيها."}]},{"no":26,"title":"قائدا الإدارتين","blocks":[{"kind":"para","text":"لا يُعزل قائد إدارة الموارد البشرية ولا قائد إدارة الضمان والجودة، ولا يُستبدل به غيره، ولا يُنقل من منصبه، ولا يُجمَّد منصبه، ولا تُنهى عضويته، إلا بيد رئيس أدِيب، أو بيد الرئيس التنفيذي بموافقة رئيس أدِيب. وما تجعله المادتان ٢٣ و٣٢ لمن يملك التعيين في منصبيهما، من نقل صاحبهما منهما وتجميدهما، يجري على هذا الوجه. ولا تُنهى عضوية المكلَّف بأحد المنصبين مدّة تكليفه إلا على هذا الوجه."}]},{"no":27,"title":"الرئيس التنفيذي","blocks":[{"kind":"para","text":"لا يعزل الرئيسَ التنفيذي، ولا يُنهي عضويته، ولا يقضي في طلب خروجه، إلا رئيس أدِيب."}]},{"no":28,"title":"رئيس أدِيب","blocks":[{"kind":"para","text":"رئيس أدِيب أعلى منصب في النادي ومرجعه الأخير، ولا يعلوه فيه أحد. يبقى في منصبه حتى يتركه، ولا يعزله أحد في النادي، ويسمّي قبل أن يترك منصبه من يخلفه، فيشغله خلفه يوم يتركه. ولا يكون الخلف إلا عضوًا في أدِيب يوم التسمية ويوم الترك، فإن ترك الرئيس منصبه ولم يسمِّ أحدًا، أو سمّى من لم يعد عضوًا، صار الرئيس التنفيذي رئيسًا. ولا يُسند منصبه بغير ذلك، ولا يُجمَّد، ولا يُكلَّف عليه، ولا تُنهى عضوية صاحبه، ولا يخرج صاحبه من العضوية وهو فيه، ولا يُحذف حسابه. ويقوم الرئيس التنفيذي مقام رئيس أدِيب عند غيابه بكل صلاحياته، ومنها ما يملكه رئيس أدِيب وحده، وليس ذلك تكليفًا، إلا ما يُشترط فيه الرئيسان معًا، كتعديل الدستور والأنظمة وإنشاء الأقسام واللجان وإلغائها، فينتظر عودته. وإذا ترك رئيس أدِيب منصبه خُيّر بين أن يبقى عضوًا، فيُسند إليه من يملك التعيين منصبًا يوم تركه، وأن يخرج من العضوية."}]},{"no":29,"title":"المنصب الخالي","blocks":[{"kind":"para","text":"إذا انتهت عضوية شخص خلت مناصبه في الحال. ويُشغل المنصب الخالي على ما في المادة ٢١، أو بالتكليف حيث يجيزه الباب الخامس."}]}]},{"title":"الباب الخامس: التكليف","articles":[{"no":30,"title":"التكليف","blocks":[{"kind":"para","text":"التكليف إسناد منصب شاغر إلى عضو إسنادًا مؤقّتًا إلى آخر يوم محدّد، فوق منصبه الأصيل. ولا تكليف على منصب مشغول نيابةً عن صاحبه الغائب."}]},{"no":31,"title":"من يكلّف","blocks":[{"kind":"para","text":"يكلّف في المنصب من يملك التعيين فيه، وهم: رئيس أدِيب، والرئيس التنفيذي، وقائد إدارة الموارد البشرية. ويجوز التكليف في المنصب المنتخب الشاغر قبل انتخابه. ولا يكلّف أحد نفسه، ويُكتب للتكليف سببه. وإذا شغر منصب أحد قائدَي الإدارتين كلّف فيه رئيس أدِيب، أو الرئيس التنفيذي بموافقة رئيس أدِيب."}]},{"no":32,"title":"الاستمرار والتجميد","blocks":[{"kind":"para","text":"للمكلِّف أن يكلّف العضو مع استمرار منصبه الأصيل، أو مع تجميده. والمنصب المجمَّد محجوز لصاحبه، بلا صلاحيات ولا وزن صوت، ولا يُسند إلى غيره، ويعود حيًّا حين ينتهي التكليف. ولا يجمّد المنصب إلا من يملك التعيين فيه، ما لم يكن عضوية لجنة."}]},{"no":33,"title":"حدود التكليف","blocks":[{"kind":"para","text":"لا يُكلَّف أحد عضوًا في إدارة الموارد البشرية ولا في إدارة الضمان والجودة. ولا يُكلَّف عضو أيٍّ من الإدارات الثلاث بمنصب منسّق قسم أو قائد لجنة أو نائبه، ولا يشمل ذلك قائدَي الإدارتين. ولا تكليف على منصب رئيس أدِيب، ولا يُكلَّف رئيس أدِيب بمنصب آخر. ولا يُكلَّف إلا عضو له منصب أصيل وليس مكلَّفًا بغيره. ويجوز أن يُكلَّف عضو في المجلس الإداري بمنصب آخر فيه، ويبقى له في المجلس صوت واحد."}]},{"no":34,"title":"ما للمكلَّف","blocks":[{"kind":"para","text":"يأخذ المكلَّف مدّة تكليفه كل ما للمنصب: السلطة، والصلاحيات، ووزن الصوت، والمسمّى بلفظ «تكليفًا»."}]},{"no":35,"title":"انتهاء التكليف","blocks":[{"kind":"para","text":"ينتهي التكليف بانقضاء آخر يوم فيه، أو بإنهائه قبله ممّن يملك التكليف في المنصب، أو بإسناد المنصب إسنادًا دائمًا ومنه إعلان فائز الانتخاب عليه، أو بانتهاء عضوية المكلَّف. والتكليف على منصب أحد قائدَي الإدارتين لا يُنهى قبل أجله، ولا يُقدَّم أجله، إلا بيد رئيس أدِيب، أو بيد الرئيس التنفيذي بموافقة رئيس أدِيب (المادة ٢٦)."}]},{"no":36,"title":"التكليف على المنصب المجمَّد","blocks":[{"kind":"para","text":"يجوز التكليف على المنصب المجمَّد تابعًا لتكليف صاحبه، ولا تاريخ له: ينتهي بعودة صاحب المنصب."}]}]},{"title":"الباب السادس: العضوية","articles":[{"no":37,"title":"الإهداء","blocks":[{"kind":"para","text":"يُهدي العضويةَ رئيسُ أدِيب أو الرئيسُ التنفيذي أو قائدُ إدارة الموارد البشرية، لمتطوّع قائم، بمنصب عضو في لجنة من لجان المجلس التشغيلي. ويكون الإهداء وفق معايير يضعها المجلس الإداري."}]},{"no":38,"title":"العضوية الجديدة","blocks":[{"kind":"para","text":"تبدأ العضوية المُهداة يوم الإهداء، وينتهي بها تطوّع صاحبها. وعلى العضو الجديد أن يستكمل سجلّ عضويته في المهلة التي يحدّدها نظام العضوية. ومن كان عضوًا من قبل تُحفظ عضويته السابقة في سجلّ النادي. ولا تسري على العضوية الجديدة إنذارات العضوية السابقة، وتبقى في سجلّه."}]},{"no":39,"title":"الخروج بالإرادة","blocks":[{"kind":"para","text":"لعضو أدِيب أن يخرج من العضوية بإرادته، بسبب مكتوب. فمن لم يكن له منصب إلا عضوية اللجنة أنهى عضويته بنفسه في الحال، ومن كان له منصب غيرها خرج بطلب يقضي فيه من يحدّده نظام العضوية. ولا يقضي أحد في طلب خروجه هو، ولا يُردّ الطلب إلا بسبب مكتوب. ولا يُحذف حساب عضو حتى تنتهي عضويته. ولا يجري شيء من هذه المادة على رئيس أدِيب (المادة ٢٨). ويقضي في طلب خروج أحد قائدَي الإدارتين رئيس أدِيب، أو الرئيس التنفيذي بموافقة رئيس أدِيب."}]},{"no":40,"title":"إنهاء العضوية","blocks":[{"kind":"para","text":"يملك إنهاء العضوية: رئيس أدِيب في كل عضو، والرئيس التنفيذي في كل عضو إلا رئيس أدِيب، ولا يُنهي عضوية أحد قائدَي الإدارتين إلا بموافقة رئيس أدِيب (المادة ٢٦)، وقائد الموارد البشرية فيمن يملك تعيينه: أعضاء إدارته، ومنسّقي الأقسام، وقادة اللجان ونوّابهم، وأعضاء اللجان، وعضو الموارد البشرية فيمن كانت مناصبه كلّها في لجان يشرف عليها. ويكون الإنهاء بسبب مكتوب وفئة من خمس: عدم التفاعل والغياب، والخروج دون إبلاغ، والخروج بطلب العضو، والمخالفة أو الإساءة، وأسباب أخرى. ولا يُشترط له إنذار سابق، ولا يُنهي أحد عضوية نفسه بهذا الطريق. ويُمكَّن العضو من أن يُسمع قبل إنهاء عضويته، إلا ما كان بطلبه أو بحدّ الإنذارات (المادة ٥٧)."}]},{"no":41,"title":"النقل إلى المتطوّعين","blocks":[{"kind":"para","text":"يجوز إنهاء العضوية مع إبقاء صاحبها متطوّعًا، ويملكه من يملك الإنهاء بشروطه. ولا يُنقل من أُنهيت عضويته لمخالفة أو إساءة، ولا من خرج دون إبلاغ، ولكلٍّ منهما أن يتطوّع بعد ذلك على ما في المادة ٦٠."}]},{"no":42,"title":"أثر انتهاء العضوية","blocks":[{"kind":"para","text":"إذا انتهت العضوية بأي طريق خلت مناصب صاحبها، وانتهى تكليفه، وصار صديقًا لأدِيب أو متطوّعًا إن نُقل، وجُمِّدت بيانات عضويته. ويبقى سجلّه في النادي: عضويته ومناصبه وما شارك فيه، وسبب خروجه وفئته."}]},{"no":43,"title":"الاستعادة","blocks":[{"kind":"para","text":"يملك استعادة العضوية من يملك إنهاءها، بعد أن يُسند إلى صاحبها منصب أصيل. والاستعادة إحياء للعضوية السابقة بتاريخها الأول. ولا تكون إلا لتصحيح إنهاء خاطئ، ومن عاد بعد خروج صحيح فطريقه التطوّع ثم الإهداء (المادة ٩)."}]}]},{"title":"الباب السابع: الانتخابات","articles":[{"no":44,"title":"المناصب المنتخبة","blocks":[{"kind":"para","text":"تُشغل بالانتخاب ثلاثة مناصب: منسّق القسم على مستوى القسم، وقائد اللجنة ونائبه على مستوى اللجنة. ولا يُفتح انتخاب إلا لمنصب شاغر، ولا يمنع المكلَّف فتحه."}]},{"no":45,"title":"الترشّح","blocks":[{"kind":"para","text":"لا يترشّح أعضاء المجلس الإداري ولا أعضاء الإدارات الثلاث. ويترشّح لمنصبي قائد اللجنة ونائبه من له منصب في اللجنة، ولمنصب منسّق القسم من له منصب في إحدى لجان القسم، على ما يفصّله نظام الانتخابات. والترشّح التزام بمسؤوليات المنصب إن فاز به المرشّح. ويجوز للمكلَّف بمنصب منتخب أن يترشّح له، ما لم يكن من أعضاء المجلس الإداري. ولمن يملك توزيع الصلاحيات (المادة ٦٦) أن يحرم عضوًا بعينه من الترشّح، بسبب مكتوب يطّلع عليه صاحبه."}]},{"no":46,"title":"الناخبون","blocks":[{"kind":"para","text":"يصوّت لمنصبي قائد اللجنة ونائبه من له منصب في اللجنة، ولمنصب منسّق القسم من له منصب في إحدى لجان القسم. ويصوّت في كل انتخاب الرئيسان وقائدا الإدارتين. والأصوات موزونة بمنصب الناخب على جدول في نظام الانتخابات، ولا يصوّت المرشّح لنفسه. ويصوّت في كل انتخاب قائد الإدارة التنفيذية إن عُيّن."}]},{"no":47,"title":"الحجب والسرّية","blocks":[{"kind":"para","text":"يُعرض بيان المرشّح على الناخبين برقمه الانتخابي لا باسمه. ولا يذكر المرشّح في بيانه ما يدلّ عليه، ولا يُفصح عن ترشّحه، ولا يطلب الأصوات. ولا يرى من صوّت لمن، ولا النتائج قبل إغلاق التصويت، إلا مديرو الانتخابات: رئيس أدِيب، والرئيس التنفيذي، وقائد إدارة الموارد البشرية، ولا يُعطى ذلك حساب النادي المؤسّسي. ويرى أعضاء إدارة الموارد البشرية النتائج بعد إغلاق التصويت. وبعد اكتمال الانتخاب يُعلن الفائز وحده، وتبقى أسماء من لم يفز ومجاميعهم محجوبة عن غير من ذُكروا."}]},{"no":48,"title":"الفوز","blocks":[{"kind":"para","text":"يفوز صاحب أعلى مجموع لأوزان أصوات التأييد. فإن لم يكن في المنصب إلا مرشّح معتمد واحد صوّت الناخبون بالتأييد أو الاعتراض، ولا يفوز إلا إذا زاد التأييد على الاعتراض. ولا يفوز عضو بمنصبين في القسم الواحد في الدورة نفسها، فيرتقي من يليه. ويُسند المنصب إلى الفائز بإعلان فوزه."}]},{"no":49,"title":"إدارة الانتخابات","blocks":[{"kind":"para","text":"يدير الانتخابات رئيس أدِيب والرئيس التنفيذي وقائد إدارة الموارد البشرية: يفتحونها، ويعلنون الفائز، ولهم التكليف على المنصب الذي تعثّر انتخابه. ويراجعون الترشّح فيعتمدونه أو يطلبون تعديله أو يعتذرون عنه، ويُسبَّب طلب التعديل والاعتذار كتابةً، ولا يُعتمد ترشّح إلا بمراجعتهم. ولهم إلغاء الانتخاب بسبب مكتوب، ويُقيَّد كل إجراء في سجلّ الانتخاب. ولإدارة الموارد البشرية استبعاد من خالف ضوابط الحجب والدعاية."}]}]},{"title":"الباب الثامن: الحقوق والواجبات","articles":[{"no":50,"title":"حقوق العضو","blocks":[{"kind":"para","text":"لعضو أدِيب:"},{"kind":"list","ordered":true,"items":["أن يصوّت ويترشّح حيث يجعل له منصبه ذلك، على ما في الباب السابع.","أن يطّلع على الإنذارات الصادرة بحقّه ولو انتهت عضويته، وعلى سبب كل قرار ممّا في المادة ٥٥.","أن يخرج من العضوية بإرادته على ما في المادة ٣٩، وأن يُجاب بسبب مكتوب إن رُدّ طلبه.","أن يتظلّم من كل قرار صدر بحقّه، على ما في المادة ٥٨."]}]},{"no":51,"title":"واجبات العضو","blocks":[{"kind":"para","text":"على عضو أدِيب:"},{"kind":"list","ordered":true,"items":["الالتزام بمهام لجنته وقسمه، أو إدارته إن كان من أعضاء الإدارات.","التزام هذا الدستور وأنظمة النادي.","صون معلومات النادي وملفّاته الداخلية، فلا يسرّبها.","حسن التعامل مع إدارة النادي وأهله.","إبلاغ إدارة الموارد البشرية قبل أن يخرج من النادي.","التجاوب مع قادة لجنته وإدارة النادي."]}]},{"no":52,"title":"المتطوّع","blocks":[{"kind":"para","text":"لمتطوّع أدِيب أن يتقدّم إلى فرص التطوّع، ويسحب طلبه ما لم يُبتّ فيه، ويعتذر بعد قبوله بسبب مكتوب ما لم يبدأ موعد الفرصة. ولكل من قُبل في فرصة وحضرها شهادة مشاركة بساعاته، ما لم تُحجب (المادة ٦٢). وعلى المتطوّع الالتزام بما قُبل فيه من فرص، وحسن التعامل مع النادي وأهله، وصون معلوماته."}]},{"no":53,"title":"صديق أدِيب","blocks":[{"kind":"para","text":"لصديق أدِيب أن ينتفع ببرامج النادي، ومنها حجز الفعاليات."}]}]},{"title":"الباب التاسع: المساءلة والتظلّم","articles":[{"no":54,"title":"لا جزاء بلا نصّ","blocks":[{"kind":"para","text":"لا يُنذَر أحد، ولا تُنهى عضويته لمخالفة، إلا على مخالفة واجب منصوص عليه في هذا الدستور أو في أنظمة النادي."}]},{"no":55,"title":"القرار المسبَّب","blocks":[{"kind":"para","text":"الإنذار، وإنهاء العضوية، وردّ طلب الخروج، ورفض طلب التطوّع، وإنهاء التطوّع، وحجب الشهادة وإبطالها: يصدر كلٌّ منها مكتوبًا بسببه. وكذلك حرمان العضو من الترشّح (المادة ٤٥). ويطّلع على كلٍّ منها صاحبه."}]},{"no":56,"title":"الإنذار","blocks":[{"kind":"para","text":"يُصدر الإنذار رئيس أدِيب والرئيس التنفيذي وقائد إدارة الموارد البشرية وأعضاؤها، كلٌّ في مدى سلطته في إنهاء العضوية (المادة ٤٠)، بتصنيف وسبب مكتوب. ولا يُنذر أحد نفسه. ولا يُنذَر أعضاء المجلس الإداري: رئيس أدِيب، والرئيس التنفيذي، وقائدا الإدارتين، ومن كُلّف بمناصبهم مدّة تكليفه. ولا يُنذَر قائد الإدارة التنفيذية إن عُيّن. ولا يُنذَر إلا عضو."}]},{"no":57,"title":"حدّ الإنذارات","blocks":[{"kind":"para","text":"من بلغ ثلاثة إنذارات سارية انتهت عضويته فور صدور الثالث، حكمًا من هذا الدستور لا بسلطة شخص. ولا يسقط الإنذار بمرور الزمن، وإنما يُلغى بقرار مسبَّب ممّن يبلغ صاحبَه مدى الإنذار في المادة ٥٦، ولو كان صاحبه اليوم غير عضو أو من أعضاء المجلس الإداري، ويبلغ الرئيسُ التنفيذي في ذلك قائدَي الإدارتين. ولا يعيد إلغاءُ الإنذار العضويةَ التي انتهت به، وإنما تُستعاد على ما في المادة ٤٣، فإن أُلغي بقبول التظلّم منه استُعيدت (المادة ٥٨)."}]},{"no":58,"title":"التظلّم","blocks":[{"kind":"para","text":"لمن صدر بحقّه قرار أن يتظلّم منه إلى الرئيسين، فيبتّان فيه معًا، ولا يُقبل إلا باتّفاقهما، فإن كان القرار من أحدهما بتّ فيه الآخر. وما صدر من رئيس أدِيب بحقّ الرئيس التنفيذي، أو من الرئيس التنفيذي بموافقة رئيس أدِيب، فالتظلّم منه إلى رئيس أدِيب، فهو المرجع الأخير. ولا يوقف التظلّم القرار، فإن قُبل أُلغي القرار، واستُعيدت العضوية على ما في المادة ٤٣ إن كان القرار إنهاءً لها أو إنذارًا انتهت به. ولا يبتّ في التظلّم من صدر بحقّه القرار، ولا من أصدره إلا ما جعلته هذه المادة لرئيس أدِيب، ولا يبتّ الرئيس التنفيذي وهو قائم مقام رئيس أدِيب في تظلّم من قرار أصدره، بل يُرجأ إلى عودته."}]},{"no":59,"title":"مساءلة المتطوّع","blocks":[{"kind":"para","text":"لا يُنذَر المتطوّع، وإنما يُنهي تطوّعه بسبب مكتوب من يملك إدارة التطوّع."}]}]},{"title":"الباب العاشر: التطوّع والشهادات","articles":[{"no":60,"title":"التطوّع","blocks":[{"kind":"para","text":"لكل صاحب حساب استكمل ملفّه وليس عضوًا أن يتطوّع، ومنه العضو السابق. ويرتّب رغباته في لجان المجلس التشغيلي، ولا يُتطوَّع لإدارات المجلس الإداري. ومن أُنهيت عضويته لمخالفة أو إساءة فلا يتطوّع إلا بإذن الرئيسين."}]},{"no":61,"title":"إدارة التطوّع","blocks":[{"kind":"para","text":"يفتح فرص التطوّع، ويقبل المتقدّمين أو يرفضهم، ويسجّل حضورهم، ويُنهي التطوّع: رئيس أدِيب، والرئيس التنفيذي، وقائد إدارة الموارد البشرية، وأعضاؤها، وحساب النادي المؤسّسي فيما يُسند إليه (المادة ٦٦). ولا رفض ولا إنهاء إلا بسبب مكتوب."}]},{"no":62,"title":"شهادة المشاركة","blocks":[{"kind":"para","text":"لكل من قُبل في فرصة وحضرها شهادة مشاركة تُثبت ساعات تطوّعه، ويُرشَّح المتميّز بجملة تُطبع فيها مع ختم «بتميّز». ويُصدرها ويحجبها ويرفع حجبها ويرشّح للتميّز ويُبطلها من يملك إدارة التطوّع (المادة ٦١). والحجب استثناء بسبب مكتوب يطّلع عليه صاحبها، ويجوز رفعه. ولا يكون الحجب إلا لمخالفة صريحة."}]},{"no":63,"title":"شهادة الخبرة","blocks":[{"kind":"para","text":"يُصدر شهادة الخبرة ويُبطلها، للعضو الحالي والسابق: رئيسُ أدِيب لكل أحد، والرئيسُ التنفيذي لكل أحد إلا رئيس أدِيب، وقائدُ إدارة الموارد البشرية لكل أحد إلا الرئيسين وقائد الضمان والجودة. ولا يُصدرها أحد لنفسه إلا رئيس أدِيب."}]},{"no":64,"title":"حجّية الشهادة","blocks":[{"kind":"para","text":"الشهادة إثبات لواقع مسجّل، ويبقى مضمونها كما كان يوم إصدارها إلا اسم صاحبها إذا صحّحه. ويتحقّق منها أي أحد برقمها. وتُبطَل بقرار مسبَّب ممّن يملك إصدارها، وتبقى في السجلّ مشطوبة."}]}]},{"title":"الباب الحادي عشر: الأنظمة والتعديل","articles":[{"no":65,"title":"الأنظمة","blocks":[{"kind":"para","text":"تفصّل هذا الدستور ستّة أنظمة: العضوية، والمناصب والصلاحيات ومعه التكليف، والانتخابات، والانضباط، والتطوّع، والشهادات. وما خالف الدستور منها لا يُعمل به."}]},{"no":66,"title":"توزيع السلطة في المنصّة","blocks":[{"kind":"para","text":"يعدّل توزيع الصلاحيات في منصّة أدِيب رئيس أدِيب. ولا يُعدَّل بما يخالف هذا الدستور وأنظمته، ولا يمارس السلطة على الأشخاص في المنصّة إلا صاحب منصب أو مكلَّف به، أو حساب النادي المؤسّسي فيما يُسنده إليه رئيس أدِيب، ما خلا إدارة الانتخابات."}]},{"no":67,"title":"العلنية","blocks":[{"kind":"para","text":"يُنشر الدستور والأنظمة علنًا في «أنظمة أدِيب» على موقع النادي، ويقرؤها أي أحد."}]},{"no":68,"title":"التعديل","blocks":[{"kind":"para","text":"يحرّر الدستورَ والأنظمةَ وينشرها الرئيسان، ويُعرض التعديل على المجلس الإداري للمشورة قبل نشره، والقرار فيه للرئيسين معًا، فلا تُنشر نسخة جديدة إلا بموافقتهما."}]},{"no":69,"title":"النسخة السارية","blocks":[{"kind":"para","text":"النسخة المنشورة لا تُعدَّل، وكل تعديل نسخةٌ جديدة لها تاريخ نفاذ. وكل واقعة تُحاسَب بالنسخة السارية يوم وقوعها."}]},{"no":70,"title":"النفاذ","blocks":[{"kind":"para","text":"يسري هذا الدستور من تاريخ نشره."}]}]}]$body$::jsonb
from public.regulations r where r.slug = 'constitution'
on conflict (regulation_id, version_no) do nothing;

-- نظام العضوية
insert into public.regulation_versions
  (regulation_id, version_no, status, effective_from, change_note, approval_note, body)
select r.id, 1, 'draft', null, 'الإصدار الأوّل', 'الإصدار الأول، أقرّه الرئيسان معًا بعد عرضه على المجلس الإداري في ١٢ أكتوبر ٢٠٢٦، ويسري من تاريخ نشره في «أنظمة أدِيب».',
  $body$[{"title":"الباب الأول: أحكام عامة","articles":[{"no":1,"title":"موضوع النظام","blocks":[{"kind":"para","text":"يفصّل هذا النظام أحكام العضوية في دستور أدِيب: الانضمام، وسجلّ العضوية، والخروج، والإنهاء، والنقل إلى المتطوّعين، وأثر انتهاء العضوية، والاستعادة. ويُقرأ مع الدستور ويُحيل إليه، وما خالفه منه لا يُعمل به (الدستور، المادتان ٣ و٦٥)."}]},{"no":2,"title":"التعريفات","blocks":[{"kind":"para","text":"يُراد بالألفاظ الآتية في هذا النظام ما بجانبها:"},{"kind":"list","ordered":false,"items":["**العضوية السارية:** عضوية بدأت ولم تنتهِ، وصاحبها «العضو».","**العضو السابق:** من انتهت عضويته ولم تُستعد، ولم تبدأ له عضوية جديدة.","**سجلّ العضوية:** بيانات العضو التي يحفظها النادي في منصّة أدِيب ويحرّرها صاحبها (المادة ١٢).","**سجلّ النادي:** ما يحفظه النادي من وقائع العضو ولا يُحرَّر: عضوياته، ومناصبه، وما شارك فيه، وطرق انتهاء عضوياته وأسبابها وفئاتها (الدستور، المادة ٤٢).","**المنصب الأصيل:** منصب العضو الدائم، لا التكليف (الدستور، المادة ٢٣)."]}]},{"no":3,"title":"لا أجل للعضوية","blocks":[{"kind":"para","text":"لا أجل للعضوية ولا تجديد لها. تبقى حتى تنتهي بأحد الطرق في المادة ٢٨."}]}]},{"title":"الباب الثاني: الانضمام","articles":[{"no":4,"title":"المُهدي","blocks":[{"kind":"para","text":"يُهدي العضوية من سمّتهم المادة ٣٧ من الدستور، أو من كُلّف بمنصب أحدهم مدّة تكليفه. ويُشترط في المُهدي أن يملك التعيين في منصب عضو اللجنة التي يُهدي إليها."}]},{"no":5,"title":"المُهدى إليه","blocks":[{"kind":"para","text":"لا تُهدى العضوية إلا لمتطوّع تطوّعه قائم، وليس عضوًا. ويضع المجلس الإداري معايير الإهداء (الدستور، المادة ٣٧) بقرار، وتُنشر ملحقًا بهذا النظام."}]},{"no":6,"title":"المنصب المُهدى","blocks":[{"kind":"para","text":"يُهدى للمتطوّع منصب عضو في لجنة قائمة من لجان المجلس التشغيلي، يختارها المُهدي، وتُعرض عليه رغبة المتطوّع الأولى. ولا يُهدى منصب في الإدارات الثلاث (الدستور، المادة ٢٢)."}]},{"no":7,"title":"التبليغ","blocks":[{"kind":"para","text":"يُبلَّغ العضو الجديد بالإهداء، وبلجنته، وبآخر يوم في مهلة استكمال سجلّه."}]},{"no":8,"title":"بدء العضوية","blocks":[{"kind":"para","text":"تبدأ العضوية يوم الإهداء (الدستور، المادة ٣٨): يُسند المنصب المُهدى إلى صاحبها، ويثبت تاريخ انضمامه بذلك اليوم، وينتهي تطوّعه بسبب «نال العضوية». فإن رُدّ إسناد المنصب لم يقع شيء من ذلك."}]},{"no":9,"title":"استكمال السجلّ","blocks":[{"kind":"para","text":"على العضو الجديد أن يستكمل سجلّ عضويته في منصّة أدِيب خلال أربعة عشر يومًا من الإهداء، ولا يدخل لوحته في المنصّة قبل أن يستكمله."}]},{"no":10,"title":"عدم الاستكمال","blocks":[{"kind":"para","text":"إذا مضت المهلة ولم يستكمل العضو سجلّه جاز لمن يملك إنهاء عضويته أن يُنهيها في فئة «عدم التفاعل والغياب»، بسبب «عدم استكمال متطلّبات الانضمام»، بعد سماعه (المادة ٢٤)."}]},{"no":11,"title":"العائد بالإهداء","blocks":[{"kind":"para","text":"إذا أُهديت العضوية لعضو سابق نشأت له عضوية جديدة بتاريخ الإهداء، وسقط عن حاله الجارية سبب إنهائه السابق وفئته، وتُحفظ عضويته السابقة في سجلّ النادي: تاريخها، وتاريخ انتهائها، وسببه، وفئته. وتجري على العائد المادتان ٣٨ و٦٠ من الدستور: في إنذارات عضويته السابقة، وفي تطوّع من أُنهيت عضويته لمخالفة أو إساءة."}]}]},{"title":"الباب الثالث: سجلّ العضوية","articles":[{"no":12,"title":"السجلّ","blocks":[{"kind":"para","text":"لكل عضو سجلّ عضوية فيه: اسمه الثلاثي بالعربية، وجنسه، وتاريخ ميلاده، ورقم هويته، وجوّاله، وبريده، وصفته من ستّ: ثانوية عامة، أو موظّف، أو دبلوم، أو بكالوريوس، أو ماجستير، أو دكتوراه. ويُطلب لحامل الدبلوم فما فوقه كلّيته وتخصّصه ورقمه الأكاديمي. وله أن يضيف ما تتيحه المنصّة من بيانات اختيارية، كحساباته في الشبكات الاجتماعية."}]},{"no":13,"title":"تحرير السجلّ","blocks":[{"kind":"para","text":"يحرّر العضو سجلّه بنفسه. ويحرّره كذلك من يدخل العضو في مداه من إنهاء العضوية (المادة ٢٢)."}]},{"no":14,"title":"سجلّ العضو السابق","blocks":[{"kind":"para","text":"إذا انتهت العضوية جُمّد سجلّها فلا يُحرَّر، إلا اسم صاحبه وجوّاله ومدينته، وتفضيله في رسائل النادي، وطلبه حذف حسابه. ويبقى في سجلّ النادي ما ذكرته المادة ٤٢ من الدستور."}]},{"no":15,"title":"الاطّلاع","blocks":[{"kind":"para","text":"يطّلع العضو، حاليًّا أو سابقًا، على سجلّ عضويته، وعلى ما في سجلّ النادي من وقائعه، وعلى سبب كل قرار صدر بحقّه ممّا في هذا النظام (الدستور، المادتان ٥٠ و٥٥). ويطّلع على سجلّ العضو الساري رئيس أدِيب، والرئيس التنفيذي، وقائدا الإدارتين، وقائد لجنته ونائبه، وحساب النادي المؤسّسي. ويطّلع على كشف الأعضاء السابقين رئيس أدِيب، والرئيس التنفيذي، وقائد إدارة الموارد البشرية، وحساب النادي المؤسّسي."}]}]},{"title":"الباب الرابع: الخروج بالإرادة","articles":[{"no":16,"title":"بابا الخروج","blocks":[{"kind":"para","text":"يخرج العضو من العضوية بإرادته (الدستور، المادة ٣٩) بأحد بابين، بحسب منصبه:"},{"kind":"list","ordered":true,"items":["**الخروج الفوري:** لمن ليس له منصب غير عضوية اللجنة. يُنهي عضويته بنفسه في الحال، بسبب مكتوب، وفئتها «الخروج بطلب العضو».","**طلب الخروج:** لمن له منصب غيرها، أصيلًا كان أو تكليفًا. يقدّم طلبًا مكتوبًا بسببه، ولا تنتهي عضويته حتى يُقبل."]},{"kind":"para","text":"ولا يجري البابان على رئيس أدِيب ما دام في منصبه (الدستور، المادة ٢٨). فإن ترك منصبه واختار الخروج انتهت عضويته يوم تركه، وفئتها «الخروج بطلب العضو»."}]},{"no":17,"title":"طلب الخروج","blocks":[{"kind":"para","text":"لا يكون للعضو إلا طلب خروج واحد قائم، وله أن يسحبه ما لم يُقضَ فيه، فتبقى عضويته كما هي. ويُغلق الطلب إذا انتهت العضوية بطريق آخر."}]},{"no":18,"title":"من يقضي في الطلب","blocks":[{"kind":"para","text":"يقضي في طلب الخروج من يقابل منصب صاحبه في هذا الجدول:"},{"kind":"table","head":["منصب صاحب الطلب","من يقضي فيه","المصدر"],"rows":[["الرئيس التنفيذي","رئيس أدِيب","قائم"],["قائد إدارة الموارد البشرية، وقائد إدارة الضمان والجودة","رئيس أدِيب، أو الرئيس التنفيذي بموافقة رئيس أدِيب","الدستور (المنصّة تجيزه للرئيس التنفيذي منفردًا)"],["قائد الإدارة التنفيذية (إن عُيّن)","رئيس أدِيب، والرئيس التنفيذي","مُقرّ"],["عضو إدارة الضمان والجودة","رئيس أدِيب، والرئيس التنفيذي، وقائد إدارة الضمان والجودة","قائم"],["عضو الإدارة التنفيذية","رئيس أدِيب، والرئيس التنفيذي","قائم"],["كل منصب غير ما سبق، عدا رئيس أدِيب","رئيس أدِيب، والرئيس التنفيذي، وقائد إدارة الموارد البشرية","قائم"]]},{"kind":"para","text":"ويقضي فيه أيٌّ ممّن في صفّه منفردًا، إلا ما نُصّ فيه على الموافقة. ومن جمع منصبًا أصيلًا وتكليفًا قُضي في طلبه بأوّل صفّ ينطبق على أحدهما، بترتيب الجدول. ويقضي المكلَّف بمنصب القاضي ما يقضي فيه صاحبه. ولا يقضي أحد في طلب خروجه هو."}]},{"no":19,"title":"القضاء في الطلب","blocks":[{"kind":"para","text":"يُقضى في الطلب بقبوله أو ردّه. فإن قُبل انتهت العضوية، وفئتها «الخروج بطلب العضو». ولا يكون الردّ إلا تأجيلًا لتسليم مهام صاحب الطلب، بسبب مكتوب يصل إليه، إلى يوم يُحدَّد لا يجاوز أربعة عشر يومًا من تقديم الطلب، فتنتهي عضويته فيه. وله أن يتظلّم من التأجيل (الدستور، المادة ٥٨)، فإن قُبل تظلّمه انتهت عضويته يوم قبوله."},{"kind":"para","text":"ويُقضى في الطلب خلال أربعة عشر يومًا من تقديمه، فإن مضت ولم يُقضَ فيه عُدّ مقبولًا، ودُوِّن أنه قُبل بمضيّ الأجل. ولا يجري ذلك على طلب الرئيس التنفيذي ولا طلب أحد قائدَي الإدارتين: فإن مضت المدّة فيهما رُفع الطلب إلى رئيس أدِيب، ولا تنتهي العضوية إلا بقضائه."}]},{"no":20,"title":"الإبلاغ قبل الخروج","blocks":[{"kind":"para","text":"الخروج بأحد البابين يفي بواجب الإبلاغ في المادة ٥١ من الدستور، ويُبلَّغ قائد إدارة الموارد البشرية بكل خروج فوري. ومن أعلن تركه النادي، قولًا أو فعلًا، ولم يخرج بأحد البابين جاز إنهاء عضويته في فئة «الخروج دون إبلاغ». أمّا الغياب وانقطاع التواصل بلا إعلان ترك ففئتهما «عدم التفاعل والغياب»."}]},{"no":21,"title":"الاطّلاع على الطلبات","blocks":[{"kind":"para","text":"يطّلع صاحب الطلب على طلبه. ويطّلع على الطلبات كلّها رئيس أدِيب، والرئيس التنفيذي، وقائدا الإدارتين."}]}]},{"title":"الباب الخامس: الإنهاء","articles":[{"no":22,"title":"مدى السلطة","blocks":[{"kind":"para","text":"يملك إنهاء العضوية من سمّتهم المادة ٤٠ من الدستور، كلٌّ في مداه منها، ومن كُلّف بمنصب أحدهم مدّة تكليفه. ويدخل العضو في مدى المُنهي إذا كانت مناصبه كلّها، الأصيلة والتكليف، ممّا يبلغه مداه، فإن كان له منصب واحد خارجه خرج من مداه كلّه. في عضو إدارة الموارد البشرية، في غيره. وما اشتُرطت فيه موافقة رئيس أدِيب دُوِّنت الموافقة في قرار الإنهاء نفسه."}]},{"no":23,"title":"الفئة والسبب","blocks":[{"kind":"para","text":"يختار المُنهي فئة واحدة من الخمس في المادة ٤٠ من الدستور، ويكتب سببًا يفصّلها. وله أن يختار سببًا من الأسباب المعتمدة في الجدول فيزيد عليه، أو يكتب سببًا من خارجها."},{"kind":"table","head":["السبب المعتمد","فئته"],"rows":[["الغياب المستمرّ عن مهام اللجنة الموكلة","عدم التفاعل والغياب"],["عدم التجاوب مع قادة اللجنة أو الإدارة","عدم التفاعل والغياب"],["عدم استكمال متطلّبات الانضمام","عدم التفاعل والغياب"],["خروج العضو من مجتمع أدِيب دون إبلاغ إدارة الموارد البشرية","الخروج دون إبلاغ"],["طلب العضو إنهاء العضوية","الخروج بطلب العضو"],["لأسباب أكاديمية أو شخصية","الخروج بطلب العضو"],["مخالفة واجب منصوص عليه في الدستور أو أنظمة النادي","المخالفة أو الإساءة"],["إساءة التعامل أو التطاول على الإدارة","المخالفة أو الإساءة"],["تسريب معلومات أو ملفّات داخلية","المخالفة أو الإساءة"]]}]},{"no":24,"title":"سماع العضو","blocks":[{"kind":"para","text":"قبل إنهاء العضوية يُبلَّغ العضو بالإنهاء المزمع وفئته وسببه، ويُمهل ثلاثة أيام ليردّ كتابةً، ثم يُقضى في الإنهاء بعد النظر في ردّه أو انقضاء المهلة. ولا يجري ذلك فيما كان بطلب العضو المكتوب، ولا في الانتهاء بحدّ الإنذارات (الدستور، المادة ٤٠)."},{"kind":"para","text":"ومن بُلّغ بإنهاء مزمع لم يكن له أن يخرج بالإرادة حتى يُقضى فيه، ويُوقَف ما قدّمه من طلب خروج إلى ذلك الحين."}]},{"no":25,"title":"قرار الإنهاء","blocks":[{"kind":"para","text":"يصدر الإنهاء مكتوبًا بفئته وسببه. ويُبلَّغ به صاحبه ويطّلع على سببه، وله أن يتظلّم منه (الدستور، المادتان ٥٥ و٥٨). وفي فئة «المخالفة أو الإساءة» يُسمّى الواجب الذي خولف من الدستور أو أنظمة النادي (الدستور، المادة ٥٤)."}]},{"no":26,"title":"حدّ الإنذارات","blocks":[{"kind":"para","text":"تنتهي العضوية ببلوغ حدّ الإنذارات (الدستور، المادة ٥٧؛ ونظام الانضباط). وتُستمدّ فئتها من صنف الإنذار الذي بُلغ به الحدّ: الغياب، والتأخّر، والتقصير، وانقطاع التواصل تُصنَّف «عدم التفاعل والغياب»؛ والسلوك ومخالفة الدستور تُصنَّفان «المخالفة أو الإساءة»؛ وما سواها «أسباب أخرى»."}]},{"no":27,"title":"النقل إلى المتطوّعين","blocks":[{"kind":"para","text":"يجوز أن يكون الإنهاء نقلًا إلى المتطوّعين في ثلاث فئات: عدم التفاعل والغياب، والخروج بطلب العضو، وأسباب أخرى (الدستور، المادة ٤١). ويصير المنقول متطوّعًا في الحال، ويعود إليه سجلّ تطوّعه السابق إن كان له، ويرتّب رغباته بنفسه. ويجري على النقل ما يجري على الإنهاء من سماع وتسبيب وتظلّم."}]}]},{"title":"الباب السادس: انتهاء العضوية","articles":[{"no":28,"title":"طرق الانتهاء","blocks":[{"kind":"para","text":"تنتهي العضوية بأحد خمسة طرق: الخروج الفوري، وقبول طلب الخروج، والإنهاء، والنقل إلى المتطوّعين، وبلوغ حدّ الإنذارات."}]},{"no":29,"title":"الأثر","blocks":[{"kind":"para","text":"إذا انتهت العضوية بأي طريق، وقع ما في المادة ٤٢ من الدستور، ومعه:"},{"kind":"list","ordered":true,"items":["ينتهي مع تكليف صاحبها كلّ تكليف تابع له، ولا يعود إليه منصبه المجمَّد بل يخلو.","يُسحب ترشّحه في الانتخابات التي لم يبدأ تصويتها، على الوحدات التي خلا منها، ويسقط إشرافه على اللجان.","يُجمَّد سجلّ عضويته (المادة ١٤).","يُدوَّن مع الانتهاء سببه، وفئته، وتاريخه، ومن أوقعه، وطريقه."]}]}]},{"title":"الباب السابع: الاستعادة","articles":[{"no":30,"title":"متى تكون","blocks":[{"kind":"para","text":"لا تُستعاد العضوية إلا لتصحيح إنهاء خاطئ (الدستور، المادة ٤٣)، ومنه قبول التظلّم من إنهاء، أو من إنذار انتهت به العضوية (الدستور، المادة ٥٨). ولا تُستعاد عضوية انتهت بخروج صحيح بالإرادة، فطريق صاحبها التطوّع ثم الإهداء (الدستور، المادتان ٩ و٤٣). ويُكتب للاستعادة سببها: الخطأ الذي تصحّحه."}]},{"no":31,"title":"إجراؤها","blocks":[{"kind":"para","text":"يستعيد العضوية من يملك إنهاءها في مداه (المادة ٢٢). فإن كانت بقبول تظلّم أجراها من بتّ فيه. ولا تُستعاد حتى يُسند إلى صاحبها منصب أصيل، ولا يكفي التكليف. ويختار من يستعيد المنصب الأصيل الذي يُسند إلى صاحبها، ممّا يملك التعيين فيه."},{"kind":"para","text":"وإذا استُعيدت عادت العضوية السابقة بتاريخ انضمامها الأوّل، وسقط عن حالها الجارية سبب إنهائها وفئته وتاريخه، وانتهى تطوّع صاحبها إن كان، وسُحبت طلباته المعلّقة في فرص التطوّع. وتبقى واقعة الإنهاء وتصحيحها في سجلّ النادي."}]}]},{"title":"الباب الثامن: أحكام ختامية","articles":[{"no":32,"title":"العضوية القائمة قبل النظام","blocks":[{"kind":"para","text":"من بدأت عضويته قبل نفاذ هذا النظام بقيت عضويته بتاريخها. ومن لم يكن له منهم سجلّ عضوية استكمله خلال أربعة عشر يومًا من نفاذه، وإلا جرى عليه ما في المادة ١٠."}]},{"no":33,"title":"النفاذ","blocks":[{"kind":"para","text":"يسري هذا النظام من تاريخ نشره في «أنظمة أدِيب» (الدستور، المادتان ٦٧ و٦٩)."}]}]}]$body$::jsonb
from public.regulations r where r.slug = 'membership'
on conflict (regulation_id, version_no) do nothing;

-- نظام المناصب والصلاحيات
insert into public.regulation_versions
  (regulation_id, version_no, status, effective_from, change_note, approval_note, body)
select r.id, 1, 'draft', null, 'الإصدار الأوّل', 'الإصدار الأول، أقرّه الرئيسان معًا بعد عرضه على المجلس الإداري في ١٢ أكتوبر ٢٠٢٦، ويسري من تاريخ نشره في «أنظمة أدِيب».',
  $body$[{"title":"الباب الأول: أحكام عامة","articles":[{"no":1,"title":"موضوع النظام","blocks":[{"kind":"para","text":"يفصّل هذا النظام الأبواب الثالث والرابع والخامس من الدستور، والمادة ٦٦ منه: إسناد المناصب والنقل والعزل والإعفاء، والتكليف والتجميد، والصلاحيات في المنصّة، وحساب النادي المؤسّسي، والإشراف، والوحدات. ويُقرأ مع الدستور ويُحيل إليه، وما خالفه منه لا يُعمل به (الدستور، المادتان ٣ و٦٥)."}]},{"no":2,"title":"التعريفات","blocks":[{"kind":"para","text":"يُراد بالألفاظ الآتية في هذا النظام ما بجانبها:"},{"kind":"list","ordered":false,"items":["**المنصب الأصيل:** منصب يشغله العضو إسنادًا دائمًا، ولكل عضو منصب أصيل واحد (الدستور، المادتان ٥ و٢٣).","**الإسناد:** شغل منصب أصيل بالتعيين، أو بالانتخاب، أو بالإهداء.","**النقل:** إسناد منصب أصيل إلى من يشغل غيره، فيخلو منصبه الأوّل (الدستور، المادة ٢٣).","**العزل:** إخراج صاحب المنصب منه بقرار ممّن يملك ذلك، مع بقائه عضوًا (الدستور، المادة ٢٥).","**الإعفاء:** إخراج صاحب المنصب منه بطلبه أو لطول غيابه، مع بقائه عضوًا (الدستور، المادة ٢٤).","**الوحدة:** القسم، أو اللجنة، أو إحدى الإدارات الثلاث.","**الصلاحية:** إذن في منصّة أدِيب بعمل أو اطّلاع، يتبع المنصب لا الشخص."]}]},{"no":3,"title":"جدول السلطة","blocks":[{"kind":"para","text":"يُسند كل منصب ويُعزل صاحبه ويُجمَّد ويُكلَّف فيه على ما في هذا الجدول، وهو جمعٌ لما في المواد ١٤ إلى ١٦ و٢١ و٢٣ و٢٥ إلى ٢٨ و٣١ إلى ٣٣ من الدستور. أمّا النقل فعلى ما في المادة ٨:"},{"kind":"table","head":["المنصب","يُسنده","يعزل صاحبه ويجمّده","يكلّف فيه"],"rows":[["رئيس أدِيب","من سمّاه سلفه من الأعضاء، فإن لم يسمِّ أحدًا أو سمّى من لم يعد عضوًا فالرئيس التنفيذي (م٢٨)","لا أحد، ولا يُجمَّد","لا تكليف عليه"],["الرئيس التنفيذي","رئيس أدِيب","رئيس أدِيب (م٢٧)","رئيس أدِيب"],["قائد الموارد البشرية، وقائد الضمان والجودة","الرئيسان معًا","رئيس أدِيب، أو الرئيس التنفيذي بموافقته (م٢٦)","رئيس أدِيب، أو الرئيس التنفيذي بموافقته (م٣١)"],["قائد الإدارة التنفيذية","الرئيس التنفيذي، إن رأى تعيينه (م١٤)","الرئيس التنفيذي","الرئيس التنفيذي"],["عضو الموارد البشرية، وعضو الضمان والجودة","قائد إدارته، أو أحد الرئيسين","من يملك إسناده","لا تكليف عليه (م٣٣)"],["عضو الإدارة التنفيذية","الرئيس التنفيذي، أو رئيس أدِيب","من يملك إسناده","من يملك إسناده"],["منسّق القسم، وقائد اللجنة، ونائبه","الانتخاب، فإن تعثّر فقائد الموارد البشرية أو أحد الرئيسين (المادة ٦)","قائد الموارد البشرية، أو أحد الرئيسين","قائد الموارد البشرية، أو أحد الرئيسين"],["عضو اللجنة","الإهداء، أو قائد الموارد البشرية أو أحد الرئيسين","لا يُعزل (م٢٥)، ويجمّده من يكلّف صاحبه (م٣٢)","قائد الموارد البشرية، أو أحد الرئيسين"]]},{"kind":"para","text":"ومن كُلّف بمنصب في الجدول أخذ سلطته فيه مدّة تكليفه (الدستور، المادة ٣٤). ولا يُسند أحد منصبًا لنفسه، ولا ينقل نفسه، ولا يجمّد منصبه. ولا تكليف على مقعد قائد الإدارة التنفيذية ما لم يُعيَّن له قائد ثم يخلو."}]}]},{"title":"الباب الثاني: شغل المناصب","articles":[{"no":4,"title":"الإسناد","blocks":[{"kind":"para","text":"يُسند المنصب من يملكه في الجدول، ويُثبت معه من أسنده ويومه. ويُبلَّغ به صاحبه، ويُقيَّد في سجلّ النشاط."}]},{"no":5,"title":"شرط العضوية","blocks":[{"kind":"para","text":"لا يُسند منصب إلا لعضو، إلا عضوية اللجنة بالإهداء، والمنصب الذي تُستعاد به العضوية (الدستور، المادة ١٠)."}]},{"no":6,"title":"المناصب المنتخبة","blocks":[{"kind":"para","text":"لا يُعيَّن في تنسيق القسم وقيادة اللجنة ونيابتها إلا بعد تعثّر انتخابه (الدستور، المادتان ١٥ و٢١؛ ونظام الانتخابات، المادة ٢٥)، ويجوز التكليف فيه قبل ذلك (الدستور، المادة ٣١). والمعتبر تعثّر انتخاب فُتح له بعد خلوّه."}]},{"no":7,"title":"المنصب المشغول","blocks":[{"kind":"para","text":"لا يُسند منصب له شاغل أصيل حتى يخلو بعزل صاحبه أو إعفائه أو نقله أو انتهاء عضويته، والمنصب المجمَّد لا يُسند (الدستور، المادتان ٢٩ و٣٢). وإن كان عليه مكلَّف انتهى تكليفه بالإسناد (الدستور، المادة ٣٥)."}]},{"no":8,"title":"النقل","blocks":[{"kind":"para","text":"لا ينقل العضوَ إلا من يملك التعيين في منصبيه القديم والجديد، إلا أن يكون القديم عضوية لجنة (الدستور، المادة ٢٣). ولا يُنقل من جُمّد منصبه حتى ينتهي تكليفه، إلا إلى المنصب المكلَّف به. ويُبلَّغ المنقول بنقله، وما كان منه بغير طلب صاحبه فبقرار مكتوب بسببه يُتظلَّم منه كالعزل (نظام الانضباط، المادة ١٧)."}]},{"no":9,"title":"القرار المشترك وغياب رئيس أدِيب","blocks":[{"kind":"para","text":"حيث يشترط الدستور «الرئيسان معًا» أو «بموافقة رئيس أدِيب» لا يمضي القرار حتى يُقيَّد في المنصّة إقرار الثاني أو موافقته، ويُحفظ مع القرار. وما يُشترط فيه الرئيسان معًا يُرجأ في غياب رئيس أدِيب إلى عودته، ويقوم الرئيس التنفيذي مقامه فيما سواه (الدستور، المادة ٢٨). ويبدأ غياب رئيس أدِيب بإعلانه وحده، وينتهي بإعلانه عودته، ويُقيَّد بدؤه وانتهاؤه. ويُقيَّد كل عمل أجراه الرئيس التنفيذي بهذه الصفة، ويُعرض ما عدّله من توزيع الصلاحيات على رئيس أدِيب عند عودته."}]}]},{"title":"الباب الثالث: ترك المنصب","articles":[{"no":10,"title":"العزل","blocks":[{"kind":"para","text":"يعزل صاحبَ المنصب من يملك ذلك في الجدول، ومنه المنصب المنتخب، ولا يعزل أحد نفسه، ويعود المعزول إلى ما في المادة ٢٥ من الدستور. ولا يُعزل عضو اللجنة ولا من لا وحدة له يعود إليها، وإنما يُنقل أو تُنهى عضويته. ويكون العزل بقرار مكتوب بسببه يُبلَّغ به صاحبه ويُقيَّد في سجلّ النشاط، ولصاحبه أن يتظلّم منه (نظام الانضباط، المادة ١٧). ومن عُزل من منصب مجمَّد بقي تكليفه، وانتهى التكليف التابع على منصبه، وعاد إلى ما في المادة ٢٥ من الدستور حيًّا."}]},{"no":11,"title":"الإعفاء بالطلب","blocks":[{"kind":"para","text":"لصاحب المنصب، غير رئيس أدِيب وعضو اللجنة، أن يطلب كتابةً إعفاءه منه والبقاء عضوًا، ممّن يملك عزله (الدستور، المادة ٢٤). ولا يقضي أحد في طلب إعفائه هو. ويُقضى في الطلب خلال أربعة عشر يومًا وإلا عُدّ مقبولًا، إلا طلب الرئيس التنفيذي أو أحد قائدَي الإدارتين فيُرفع إلى رئيس أدِيب، ولا يُعفى إلا بقضائه (الدستور، المادتان ٢٦ و٢٧). ولا يُردّ الطلب إلا تأجيلًا لتسليم المهامّ إلى أربعة عشر يومًا من الطلب، فيُعفى في اليوم المحدَّد. ويعود المُعفى إلى ما يعود إليه المعزول (الدستور، المادة ٢٥)، ومن لا وحدة له يعود إليها لا يُعفى حتى يُسند إليه منصب."}]},{"no":12,"title":"الغياب","blocks":[{"kind":"para","text":"لا نيابة عن صاحب منصب غائب غير رئيس أدِيب، ولا تكليف على منصبه نيابةً عنه (الدستور، المادتان ٢٤ و٣٠). فإن طال غيابه عن مهامّ منصبه أعفاه منه من يملك عزله بتقديره، بقرار مكتوب بسببه، ثم يُشغل المنصب أو يُكلَّف فيه (الدستور، المادة ٢٤)."}]}]},{"title":"الباب الرابع: التكليف والتجميد","articles":[{"no":13,"title":"التكليف","blocks":[{"kind":"para","text":"يكلّف في المنصب من يملك ذلك في الجدول، بقرار يُكتب فيه سببه وآخر يوم فيه، ولا يكون آخره في الماضي (الدستور، المادتان ٣٠ و٣١). ولا يكلّف أحد نفسه، ولا يُكلَّف إلا عضو له منصب أصيل وليس مكلَّفًا بغيره، ولا تكليف على منصب مشغول نيابةً عن صاحبه الغائب، ولا على خلاف المادة ٣٣ من الدستور. ويأخذ المكلَّف كل ما للمنصب، ومنه سلطته في الجدول، ويُسمّى فيه «تكليفًا» (الدستور، المادة ٣٤). ويُبلَّغ المكلَّف بتكليفه وأجله، ثم بقرب انقضائه قبل ثلاثة أيام."}]},{"no":14,"title":"الأجل والتمديد","blocks":[{"kind":"para","text":"لا حدّ لمدّة التكليف. ويُنهي التكليفَ على منصب أحد قائدَي الإدارتين قبل أجله، أو يُقدِّم أجله، رئيسُ أدِيب، أو الرئيسُ التنفيذي بموافقته (الدستور، المادة ٣٥). ويُمدّ التكليف قبل انقضائه بقرار مكتوب بسببه ممّن يملك التكليف في المنصب، ويمدّه على منصب أحد قائدَي الإدارتين رئيسُ أدِيب، أو الرئيسُ التنفيذي بموافقته."}]},{"no":15,"title":"انتهاء التكليف","blocks":[{"kind":"para","text":"ينتهي التكليف على ما في المادة ٣٥ من الدستور، ويُنفَّذ انقضاء أجله آليًّا بعد آخر يوم فيه. ويُنهيه قبل أجله من يملك التكليف في المنصب، ولا يُنهيه المكلَّف بنفسه. وللمكلَّف أن يطلب إنهاء تكليفه، فيُقضى في طلبه خلال سبعة أيام، وإلا رُفع إلى رئيس أدِيب. ويُكتب سبب الإنهاء المبكّر ويُبلَّغ به المكلَّف."}]},{"no":16,"title":"التجميد","blocks":[{"kind":"para","text":"للمكلِّف أن يُبقي منصب المكلَّف الأصيل حيًّا أو يجمّده، ولا يجمّده إلا من يملك التعيين فيه، إلا عضوية اللجنة. والمجمَّد محجوز لصاحبه بلا صلاحية ولا وزن صوت، ولا يُسند، ويعود حيًّا بانتهاء التكليف، ويجوز التكليف عليه تابعًا لتكليف صاحبه حتى يعود (الدستور، المادتان ٣٢ و٣٦). ولا يُجمَّد منصب رئيس أدِيب (الدستور، المادة ٢٨)، ولا يجمّد منصب الرئيس التنفيذي إلا رئيس أدِيب. والتجميد بغير طلب صاحبه بقرار مكتوب بسببه يُتظلَّم منه."}]}]},{"title":"الباب الخامس: الصلاحيات في المنصّة والإشراف","articles":[{"no":17,"title":"توزيع الصلاحيات","blocks":[{"kind":"para","text":"يعدّل توزيع الصلاحيات في المنصّة رئيس أدِيب وحده، ولا يُعدَّل بما يخالف الدستور وأنظمته (الدستور، المادة ٦٦). وتتبع الصلاحيات المناصب لا الأشخاص، فلا تُمنح صلاحية لشخص خارج منصبه ولا تُنزع منه، إلا ما يُسند إلى حساب النادي (المادة ١٩)، والحرمان من الترشّح (نظام الانتخابات، المادة ١١). ويُقيَّد كل تعديل في التوزيع بفاعله ويومه وما تغيّر."}]},{"no":18,"title":"السلطة على الأشخاص","blocks":[{"kind":"para","text":"السلطة على الأشخاص كل عمل يقع على شخص بعينه: الإسناد والعزل والنقل والتكليف والتجميد والإشراف، والإهداء والإنذار وإنهاء العضوية، وقبول التطوّع ورفضه وإنهاؤه، والشهادات. ولا يمارسها في المنصّة إلا صاحب منصب أو مكلَّف به في حدود الجدول والأنظمة، أو حساب النادي فيما يُسنده إليه رئيس أدِيب (المادة ١٩)، ما خلا إدارة الانتخابات (الدستور، المادة ٦٦). ويطّلع على بيانات الأعضاء والمتطوّعين من جعلته الأنظمة له (نظام العضوية، المادة ١٥)."}]},{"no":19,"title":"حساب النادي المؤسّسي","blocks":[{"kind":"para","text":"يُسند رئيس أدِيب إلى حساب النادي ما يشاء من الصلاحيات التي ليست سلطة على الأشخاص، وما يُسنده إليه من السلطة على الأشخاص يكون بقرار مكتوب يُنشر ملحقًا بهذا النظام. ولا يُسند إليه ما جعله الدستور لأصحاب مناصب بأعيانهم: الإسناد والعزل والتكليف والإشراف، والإهداء، والإنذار وإنهاء العضوية، وشهادة الخبرة، وإدارة الانتخابات، وتوزيع الصلاحيات، وإنشاء الوحدات (الدستور، المواد ١٨ و١٩ و٢١ و٢٥ و٣١ و٣٧ و٤٠ و٥٦ و٦٣ و٦٦). وله فيما يُسند إليه إدارة التطوّع وشهادة المشاركة (الدستور، المادتان ٦١ و٦٢)."}]},{"no":20,"title":"المعاينة","blocks":[{"kind":"para","text":"لرئيس أدِيب أن يعاين المنصّة بهويّة أيّ صاحب حساب، فيرى ما يراه، ويُنفَّذ ما يعمله فيها بسلطة المُعايَن ويُنسب إليه في السجلّ. ويُجلس للمعاينة في المقعد الشاغر شاغل مؤقّت لا يُعدّ إسنادًا، ويُخلى المقعد بانتهائها."}]},{"no":21,"title":"الإشراف","blocks":[{"kind":"para","text":"يوزّع الإشراف على لجان المجلس التشغيلي ويسحبه قائد كل إدارة بين أعضاء إدارته، ويملك توزيعه وسحبه الرئيسان في الإدارتين كلتيهما، ولا يشرف على اللجنة الواحدة أكثر من عضو من كل إدارة، ولا تشرف الإدارة التنفيذية (الدستور، المادة ١٩). ولعضو الموارد البشرية المشرف الإنذار وإنهاء العضوية فيمن كانت مناصبه كلّها في لجان يشرف عليها (الدستور، المادتان ٤٠ و٥٦)، ولعضو الضمان والجودة المشرف المتابعة والاطّلاع دون سلطة على الأشخاص (الدستور، المادة ١٦). ويسقط الإشراف بانتهاء عضوية المشرف (نظام العضوية، المادة ٢٩). ويسقط كذلك بخروجه من إدارته، ويُعلَّق إشراف من جُمّد منصبه، ولمن يملك توزيعه إسناده إلى غيره حتى يعود. ويُبلَّغ المشرف بإسناد الإشراف وسحبه."}]}]},{"title":"الباب السادس: الوحدات وأحكام ختامية","articles":[{"no":22,"title":"الوحدات","blocks":[{"kind":"para","text":"يُنشئ الرئيسان معًا الأقسام واللجان ويلغيانها، ولا تُنشأ إدارة ولا تُلغى إلا بتعديل الدستور (الدستور، المادة ١٨). ويغيّران معًا اسم القسم أو اللجنة."}]},{"no":23,"title":"إلغاء الوحدة ونقلها","blocks":[{"kind":"para","text":"لا يُلغى قسم وفيه لجان، ولا لجنة وفيها منصب مشغول أو تكليف أو إشراف أو انتخاب لم يكتمل ولم يُلغَ، حتى يُنقل أصحاب مناصبها ويُسحب إشرافها وينتهي انتخابها. ويبقى سجلّ الوحدة وسجلّ من كان فيها. ولا تُنقل لجنة من قسم إلى آخر إلا بالرئيسين معًا."}]},{"no":24,"title":"القائم يوم النفاذ","blocks":[{"kind":"para","text":"تبقى المناصب والتكليفات والإشراف القائمة يوم نفاذ هذا النظام على حالها، ويجري عليها حكمه من يومه. ويُنزع من حساب النادي يوم النفاذ ما تمنعه المادة ١٩، ويُصدر رئيس أدِيب ملحقها خلال ثلاثين يومًا، وإلى صدوره يبقى للحساب ما بيده من إدارة التطوّع وشهادة المشاركة، ولا يمارس غيرهما من السلطة على الأشخاص."}]},{"no":25,"title":"النفاذ","blocks":[{"kind":"para","text":"يسري هذا النظام من تاريخ نشره في «أنظمة أدِيب» (الدستور، المادتان ٦٧ و٦٩)."}]}]}]$body$::jsonb
from public.regulations r where r.slug = 'positions'
on conflict (regulation_id, version_no) do nothing;

-- نظام الانتخابات
insert into public.regulation_versions
  (regulation_id, version_no, status, effective_from, change_note, approval_note, body)
select r.id, 1, 'draft', null, 'الإصدار الأوّل', 'الإصدار الأول، أقرّه الرئيسان معًا بعد عرضه على المجلس الإداري في ١٢ أكتوبر ٢٠٢٦، ويسري من تاريخ نشره في «أنظمة أدِيب».',
  $body$[{"title":"الباب الأول: أحكام عامة","articles":[{"no":1,"title":"موضوع النظام","blocks":[{"kind":"para","text":"يفصّل هذا النظام الباب السابع من الدستور: فتح الانتخاب وإدارته، والترشّح، والتصويت، والفوز، وتعثّر الانتخاب وإلغاءه، والتظلّم فيه. ويُقرأ مع الدستور ويُحيل إليه، وما خالفه منه لا يُعمل به (الدستور، المادتان ٣ و٦٥)."}]},{"no":2,"title":"التعريفات","blocks":[{"kind":"para","text":"يُراد بالألفاظ الآتية في هذا النظام ما بجانبها:"},{"kind":"list","ordered":false,"items":["**المقعد:** منصب منتخب في وحدته: تنسيق قسم بعينه، أو قيادة لجنة بعينها أو نيابتها (الدستور، المادة ٤٤).","**الانتخاب:** إجراء شغل مقعد واحد، من فتحه إلى اكتماله بإعلان الفائز أو إلغائه.","**مديرو الانتخابات:** رئيس أدِيب، والرئيس التنفيذي، وقائد إدارة الموارد البشرية (الدستور، المادة ٤٩)، ومن كُلّف بمنصب أحدهم مدّة تكليفه.","**الترشّح القائم:** ما كان قيد المراجعة، أو مطلوبًا تعديله، أو معتمَدًا.","**التزكية:** انتخاب ليس فيه عند فتح التصويت أو إعادته إلا مرشّح معتمَد واحد، فيُصوَّت فيه بالتأييد أو الاعتراض (الدستور، المادة ٤٨).","**الدورة:** في حكم المقعدين (المادة ٢٧)، كل مقعد في القسم نفسه أُعلن فائزه منذ فُتح باب الترشّح في المقعد المنظور فيه."]}]},{"no":3,"title":"مراحل الانتخاب","blocks":[{"kind":"para","text":"يمرّ الانتخاب بمراحله على الترتيب: باب الترشّح مفتوح، ثم مغلق، ثم التصويت مفتوح، ثم مغلق، ثم يكتمل بإعلان الفائز. ولا رجوع فيها إلا إعادة فتح باب الترشّح ما لم يُفتح التصويت. ويُلغى الانتخاب في أي مرحلة قبل اكتماله (المادة ٢٩)، ولا يُستأنف ملغًى ولا مكتمل. إلا ما توجبه إعادة التصويت أو قبول التظلّم (المواد ١٦ و٢٦ و٣١)."}]}]},{"title":"الباب الثاني: إدارة الانتخابات","articles":[{"no":4,"title":"مديرو الانتخابات","blocks":[{"kind":"para","text":"يتولّى أعمال الانتخاب مديروه، ويكفي في كل عمل أحدهم: فتحه، ومراجعة الترشّح، وضبط المواعيد والمراحل، وإعلان الفائز، والتكليف على المقعد المتعثّر، والإلغاء (الدستور، المادة ٤٩). ولا يتولّى شيئًا منها غيرهم، ولا حساب النادي المؤسّسي (الدستور، المادة ٦٦). وأمّا الاستبعاد فلإدارة الموارد البشرية (المادة ١٦)."}]},{"no":5,"title":"الاطّلاع","blocks":[{"kind":"para","text":"يطّلع على الانتخاب كلٌّ بقدر ما يلي (الدستور، المادة ٤٧):"},{"kind":"list","ordered":false,"items":["**مديرو الانتخابات:** على كل شيء فيه وفي كل مرحلة، ومنه من صوّت لمن.","**أعضاء إدارة الموارد البشرية:** على هويّات المرشّحين، وسجلّ الانتخاب، ومن شارك في التصويت، في كل مرحلة، وعلى النتائج بعد إغلاق التصويت. ولا يرون لمن صوّت أحد.","**المرشّح:** على ترشّحه وقرار مراجعته، ولا يرى غيره من المرشّحين إلا كما يراهم الناخب.","**الناخب:** بعد فتح التصويت، على بيانات المرشّحين المعتمَدين وملفّاتهم بأرقامهم، وعلى صوته.","**غيرهم:** بعد اكتمال الانتخاب، على الفائز وحده بلا مجاميع."]},{"kind":"para","text":"ولا يطّلع حساب النادي المؤسّسي على النتائج، ولا على أسماء من لم يفز (الدستور، المادة ٤٧). ولا على هويّات المرشّحين، ولا على سجلّ الانتخاب."}]},{"no":6,"title":"سجلّ الانتخاب","blocks":[{"kind":"para","text":"يُقيَّد في سجلّ الانتخاب كل إجراء فيه بفاعله ووقته، وبسببه إن كان له سبب (الدستور، المادة ٤٩)، وما جرى آليًّا يُقيَّد بلا فاعل. ولا يُحذف انتخاب ولا ترشّح ولا صوت، وإنما يُلغى الانتخاب وينتهي الترشّح."}]},{"no":7,"title":"الإبلاغ","blocks":[{"kind":"para","text":"يُبلَّغ في منصّة أدِيب ناخبو المقعد بفتح الانتخاب، وبإغلاق باب الترشّح، وبفتح التصويت وموعد إغلاقه، وبإعلان الفائز أو الإلغاء أو التكليف على المقعد. ويُبلَّغ المرشّح بكل قرار في ترشّحه، والمديرون بكل ترشّح وبتعثّر الانتخاب."}]},{"no":8,"title":"فتح الانتخاب","blocks":[{"kind":"para","text":"يفتح الانتخابَ أحدُ مديريه لمقعد شاغر، ولا يمنع فتحه أن يكون عليه مكلَّف، ويمنعه أن يكون المقعد مجمَّدًا لصاحبه (الدستور، المادتان ٣٢ و٤٤). ولا يكون للمقعد إلا انتخاب واحد لم يكتمل ولم يُلغَ، وبفتحه يُفتح باب الترشّح. ولا يُلغي التكليفُ على المقعد انتخابَه القائم."}]}]},{"title":"الباب الثالث: الترشّح","articles":[{"no":9,"title":"من يترشّح","blocks":[{"kind":"para","text":"يترشّح لقيادة اللجنة ونيابتها من له منصب فيها، ولتنسيق القسم من له منصب في إحدى لجانه، أصيلًا كان المنصب أو تكليفًا (الدستور، المادة ٤٥). ولا يترشّح أعضاء المجلس الإداري، ولا أعضاء الإدارات الثلاث، ولا حساب النادي المؤسّسي. ويترشّح المكلَّف بالمقعد له. ولا يُشترط للترشّح غير ما في هذا النظام، ولا يُمنع منه أحد بتوزيع الصلاحيات إلا بالحرمان (المادة ١١). ومن جُمّد منصبه بتكليف لم يترشّح إلا للمقعد المكلَّف به، فإن فاز به انتهى تكليفه وأُسند إليه (الدستور، المادة ٣٥)."}]},{"no":10,"title":"قيود الترشّح","blocks":[{"kind":"para","text":"لا يترشّح أحد لمقعد دون منصبه الأصيل، فلا يترشّح قائد اللجنة لنيابتها. ولا يكون للعضو ترشّح قائم في قسمين معًا، وله في القسم الواحد أن يترشّح لأكثر من مقعد (المادة ٢٧). ولا يترشّح في الانتخاب الواحد إلا مرّة: فمن اعتُذر عن ترشّحه لم يتقدّم فيه من جديد، ومن انسحب لم يتقدّم إلا أن يُرجَع (المادة ١٥). ولا يُشترط للترشّح مدّة في العضوية، ولا خلوّ من الإنذارات."}]},{"no":11,"title":"الحرمان من الترشّح","blocks":[{"kind":"para","text":"لرئيس أدِيب أن يحرم عضوًا بعينه من الترشّح، بقرار مكتوب بسببه يُبلَّغ به صاحبه (الدستور، المادتان ٤٥ و٦٦). ويُذكر في القرار أجله، ولا يجاوز سنة من صدوره، وله رفعه قبل أجله. ولا يقع على ترشّح فُتح تصويته، وينتهي به ما قبل ذلك من ترشّح قائم."}]},{"no":12,"title":"الالتزام","blocks":[{"kind":"para","text":"الترشّح التزام بمسؤوليات المقعد إن فاز به المرشّح (الدستور، المادة ٤٥)، ويُقرّ المرشّح عند تقديمه بأن بيانات ترشّحه صحيحة وتخصّه. ويُقرّ بأحكام هذا النظام، وتُعرض عليه إحالة إليه."}]},{"no":13,"title":"البيان والرقم","blocks":[{"kind":"para","text":"يتقدّم المرشّح ببيان مكتوب لا يقلّ عن مئة حرف ولا يزيد على أربعة آلاف، وله أن يرفق به ملفًّا واحدًا، ولا يذكر فيهما اسمه ولا ما يدلّ عليه (الدستور، المادة ٤٧). ويُمنح رقمًا انتخابيًّا بأسبقية تقدّمه، لا يتغيّر ولا يُعطى لغيره، ويُعرض بيانه وملفّه على الناخبين به وحده. ولا يُعدّ مخالفةً منه ما كشفته المنصّة من غير فعله."}]},{"no":14,"title":"المراجعة","blocks":[{"kind":"para","text":"يراجع الترشّح أحدُ مديري الانتخابات، فيعتمده، أو يطلب تعديله، أو يعتذر عنه، ويُكتب سبب طلب التعديل والاعتذار ويطّلع عليه المرشّح (الدستور، المادة ٤٩). ولا يُبتّ إلا في ترشّح قيد المراجعة، فالمطلوب تعديله يُعدَّل أولًا. والاعتماد والاعتذار لا يُعاد النظر فيهما بالمراجعة. ولا يُعتذر عن ترشّح إلا لأنه لا يجوز لصاحبه بالمواد ٩ إلى ١١، أو لأن بيانه يخالف المادة ٤٧ من الدستور أو حسن التعامل، أو لا يتّصل بالمقعد. ويُقدَّم طلب التعديل على الاعتذار فيما يُصلحه التعديل، ويُضرب للتعديل أجل لا يقلّ عن يومين ولو أُغلق باب الترشّح، فإن مضى ولم يُعدَّل انتهى الترشّح."}]},{"no":15,"title":"التعديل والانسحاب والإرجاع","blocks":[{"kind":"para","text":"لا يعدّل الترشّح إلا صاحبه، ما دام قيد المراجعة أو مطلوبًا تعديله وباب الترشّح مفتوح، فيعود قيد المراجعة ويسقط القرار السابق، ولا يُعدَّل المعتمَد. وللمرشّح أن ينسحب ما لم يُفتح التصويت. ويُعدِّل المطلوبَ تعديله في أجله ولو أُغلق الباب (المادة ١٤). ولا يسحب المدير ترشّحًا إلا بطلب صاحبه، ولا يُرجعه إلا بطلبه أو لأن سحب المدير له كان خطأ، وذلك قبل فتح التصويت، فيعود قيد المراجعة."}]},{"no":16,"title":"الاستبعاد وأثر انتهاء الترشّح","blocks":[{"kind":"para","text":"لإدارة الموارد البشرية أن تستبعد من خالف من المرشّحين ضوابط الحجب والدعاية (المادة ٢٢؛ والدستور، المادتان ٤٧ و٤٩). يُصدره قائدها، أو أحد أعضائها بموافقته مدوَّنةً في القرار، بقرار مكتوب بسببه، بعد أن يُمهَل المرشّح يومًا ليُجيب، في أي مرحلة قبل إعلان الفائز."},{"kind":"para","text":"وإذا انتهى ترشّح بعد فتح التصويت، باستبعاد أو بغيره، بطلت الأصوات التي نالها، وعُلِّمت ولم تُحذف. فإن بقي مرشّحان معتمَدان فأكثر صوّت من بطلت أصواتهم من جديد ما دام التصويت مفتوحًا، فإن كان قد أُغلق أُعيد فتحه لهم يومين. وإن بقي مرشّح واحد أُعيد التصويت من أوّله بالتأييد أو الاعتراض (الدستور، المادة ٤٨). وإن لم يبقَ أحد تعثّر الانتخاب (المادة ٢٥)."}]},{"no":17,"title":"فقد الأهليّة","blocks":[{"kind":"para","text":"من انتهت عضويته وهو مرشّح سُحب ترشّحه ما لم يُفتح التصويت (نظام العضوية، المادة ٢٩). وإن كان قد فُتح انتهى ترشّحه وجرى على الأصوات التي نالها ما في المادة ١٦، لأن المنصب لا يُسند إلا لعضو (الدستور، المادة ١٠). ومن خرج من نطاق المقعد بنقل طلبه، أو دخل إحدى الإدارات الثلاث، انتهى ترشّحه، ومن خرج منه بغير طلبه بقي ترشّحه حتى يكتمل الانتخاب."}]}]},{"title":"الباب الرابع: التصويت","articles":[{"no":18,"title":"الناخبون","blocks":[{"kind":"para","text":"يصوّت لقيادة اللجنة ونيابتها من له منصب فيها، ولتنسيق القسم من له منصب في إحدى لجانه، ويصوّت في كل انتخاب رئيس أدِيب، والرئيس التنفيذي، وقائدا الإدارتين (الدستور، المادة ٤٦). ويُعدّ في ذلك المنصب المكلَّف به، ولا يُعدّ المجمَّد (الدستور، المادتان ٣٢ و٣٤). وتُعتبر الأهليّة يوم الإدلاء بالصوت، فلا يبطل صوت بتغيّر منصب صاحبه بعده. ويصوّت في كل انتخاب قائد الإدارة التنفيذية إن عُيّن."}]},{"no":19,"title":"الأوزان","blocks":[{"kind":"para","text":"يُوزَن صوت الناخب بمنصبه على هذا الجدول (الدستور، المادة ٤٦)، فإن كان له أكثر من منصب أُخذ أعلاها، ويُثبت الوزن مع الصوت يوم الإدلاء به:"},{"kind":"table","head":["المنصب","الوزن"],"rows":[["رئيس أدِيب، والرئيس التنفيذي","٤"],["قائد إدارة الموارد البشرية، وقائد إدارة الضمان والجودة","٣٫٥"],["منسّق القسم","٢٫٥"],["قائد اللجنة","٢"],["نائب قائد اللجنة","١٫٥"],["عضو اللجنة","١"]]},{"kind":"para","text":"ولقائد الإدارة التنفيذية إن عُيّن وزن قائدَي الإدارتين (الدستور، المادة ٢٠). ولا يصوّت أعضاء الإدارات الثلاث ولا حساب النادي المؤسّسي، إذ لا منصب لهم في اللجان."}]},{"no":20,"title":"الإدلاء بالصوت","blocks":[{"kind":"para","text":"لكل ناخب صوت واحد في الانتخاب، يُعطيه لمرشّح معتمَد واحد، ولا بطاقة بلا مرشّح. ولا يصوّت المرشّح لنفسه، وله أن يصوّت لغيره في المقعد الذي يترشّح له. ولا يكون الاعتراض إلا في التزكية. ويُختم الصوت بالإدلاء به فلا يُعدَّل ولا يُحذف. إلا أن يبطل على ما في المادة ١٦، أو يُعاد التصويت على ما في المادتين ٢٦ و٣١."}]},{"no":21,"title":"السرّية","blocks":[{"kind":"para","text":"لا يطّلع على صوت أحد إلا هو ومديرو الانتخابات (الدستور، المادة ٤٧). ومن اطّلع بحكم عمله على هويّة مرشّح أو صوت ناخب لم يُفشه."}]},{"no":22,"title":"الحجب والدعاية","blocks":[{"kind":"para","text":"لا يدلّ المرشّح على نفسه في بيانه، ولا يُفصح عن ترشّحه، ولا يدعو لنفسه، ولا يطلب الأصوات، في مجموعات أدِيب ولا خارجها (الدستور، المادة ٤٧). ولا يدعو غيره لمرشّح ولا يكشف هويّته، وهو واجب يُنذَر على مخالفته (نظام الانضباط، المادة ٣)."}]}]},{"title":"الباب الخامس: المواعيد والفوز والتعثّر","articles":[{"no":23,"title":"المواعيد","blocks":[{"kind":"para","text":"يُضرب لإغلاق باب الترشّح موعد عند فتحه أو بعده، ولإغلاق التصويت موعد عند فتحه، ويُنفَّذ كل موعد آليًّا بحلوله. ولمديري الانتخابات أن يعيدوا فتح باب الترشّح ما لم يُفتح التصويت، فيسقط موعده السابق. ولا يُغلق باب الترشّح قبل ثلاثة أيام من فتحه، ولا التصويت قبل يومين من فتحه. ولا يُقدَّم موعد إغلاق التصويت ولا يُرفع بعد فتحه، ولا يُمدّ إلا مرّة قبل حلوله بسبب مكتوب يُبلَّغ به الناخبون. ولا يُعاد فتح باب الترشّح إلا بسبب مكتوب."}]},{"no":24,"title":"إغلاق الترشّح وفتح التصويت","blocks":[{"kind":"para","text":"يُغلق باب الترشّح بموعده أو بيد أحد المديرين، ولا يُغلق إلا وفيه ترشّح قائم. ولا يُفتح التصويت إلا وباب الترشّح مغلق، ولا ترشّح فيه قيد المراجعة أو مطلوب تعديله، وفيه مرشّح معتمَد على الأقل. ولا يُفتح حيث تمنعه المادة ٣١."}]},{"no":25,"title":"تعثّر الانتخاب","blocks":[{"kind":"para","text":"يتعثّر الانتخاب إذا حلّ موعد إغلاق الترشّح ولا ترشّح قائم فيه، أو سقطت التزكية. ويتعثّر كذلك إذا أُغلق باب الترشّح ثم لم يبقَ فيه ترشّح قائم، أو لم يبقَ فيه بعد فتح التصويت مرشّح معتمَد، أو أُغلق التصويت التنافسي ولم ينل أحد فيه صوتًا. فإذا تعثّر قضى فيه مديرو الانتخابات: بمدّ باب الترشّح أو إعادة فتحه ما لم يُلغَ، أو بتعيين شاغل للمقعد (الدستور، المادة ٢١)، أو بالإلغاء، ولهم مع أيٍّ منها التكليف عليه (الدستور، المادة ٤٩). ولا يُعيَّن عليه ولا يُكلَّف من سقطت تزكيته فيه."}]},{"no":26,"title":"الفوز","blocks":[{"kind":"para","text":"يفوز صاحب أعلى مجموع لأوزان أصوات التأييد، ولا يفوز المرشّح في التزكية إلا إذا زاد وزن التأييد على وزن الاعتراض (الدستور، المادة ٤٨). ولا يفوز في الانتخاب التنافسي من لم ينل صوتًا. ويُعمل بالمادة ٢٧ قبل الفصل في التعادل، فإن تعادل اثنان فأكثر في الأعلى فاز أكثرهم مصوّتين، فإن تساووا في ذلك أيضًا أُعيد التصويت بينهم يومين، فإن تعادلوا ثانيةً فاز أسبقهم ترشّحًا."}]},{"no":27,"title":"مقعدان في القسم","blocks":[{"kind":"para","text":"لا يفوز عضو بمقعدين في القسم الواحد في الدورة نفسها (الدستور، المادة ٤٨): فمن تصدّر أكثر من مقعد احتفظ بما عيّنه مفضَّلًا، فإن لم يعيّن فبأعلاها: تنسيق القسم، ثم قيادة اللجنة، ثم نيابتها، ويرتقي في غيره من يليه. ولا يُعلن مقعد منفردًا ما دام أحد مرشّحيه المعتمَدين يخوض مقعدًا آخر في القسم لم يُحسم، بل تُعلن مقاعد القسم معًا. وإن تساوت رتبة المقعدين فبأسبقهما ترشّحًا، ولا يرتقي من لم ينل صوتًا. ويجري ذلك في التزكية، فمن احتفظ بغيرها انتهى ترشّحه فيها."}]},{"no":28,"title":"إعلان الفائز","blocks":[{"kind":"para","text":"يُعلن الفائزَ أحدُ مديري الانتخابات بعد إغلاق التصويت، ولا يُعلن إلا من أوجبته المادتان ٢٦ و٢٧. وبإعلانه يكتمل الانتخاب، ويُسند المقعد إلى الفائز، فإن كان له منصب آخر نُقل منه (الدستور، المادة ٢٣)، وينتهي التكليف على المقعد إن كان (الدستور، المادة ٣٥). ولا يُعلن لغير من في المادة ٥ إلا الفائز. ويُعلن خلال ثلاثة أيام من إغلاق تصويت آخر مقعد مرتبط به في القسم أو جولة الإعادة، ما لم تمنعه المادة ٣١، فإن مضى الأجل أعلنته المنصّة آليًّا."}]},{"no":29,"title":"الإلغاء","blocks":[{"kind":"para","text":"لمديري الانتخابات إلغاؤه قبل اكتماله بقرار مكتوب بسببه (الدستور، المادة ٤٩). ويُحفظ ما فيه من ترشّح وصوت، وما أُلغي آليًّا بسقوط التزكية قُيّد سببه مع وزنَي التأييد والاعتراض. ولا يكون سبب الإلغاء بعد فتح التصويت إلا تعثّره، أو خللًا يمسّ صحّته يُسمّى في القرار."}]}]},{"title":"الباب السادس: التظلّم وأحكام ختامية","articles":[{"no":30,"title":"التظلّم في الانتخاب","blocks":[{"kind":"para","text":"لمن صدر بحقّه قرار في الانتخاب أن يتظلّم منه (الدستور، المادة ٥٨): فيتظلّم المرشّح من الاعتذار عن ترشّحه، ومن استبعاده، ومن انتهاء ترشّحه بغير طلبه، ويتظلّم مرشّحو الانتخاب المعتمَدون من إلغائه ومن إعلان فائزه. ويجري في ذلك نظام الانضباط (المواد ١٧ إلى ٢٢)، إلا أن التظلّم يُقدَّم خلال يومين من الإبلاغ بالقرار، ويُبتّ فيه خلال ثلاثة أيام من تقديمه. وما وقع آليًّا فالتظلّم منه إلى الرئيسين معًا. والتظلّم من الحرمان من الترشّح على آجال نظام الانضباط، إلا أن ينتهي به ترشّح قائم فعلى آجال هذا النظام."}]},{"no":31,"title":"أثره","blocks":[{"kind":"para","text":"لا يُفتح التصويت ولا يُعلن الفائز قبل مضيّ أجل التظلّم من اعتذار أو استبعاد أو حرمان أنهى فيه ترشّحًا، ولا ما دام تظلّم منه لم يُبتّ فيه، ولا في أجل إجابة مرشّح يُراد استبعاده (المادة ١٦)، ويُمدّ أجل الإعلان بقدر ذلك. فإن قُبل تظلّم من اعتذار أو استبعاد أو حرمان بعد فتح التصويت بطلت أصوات الانتخاب وأُعيد التصويت من أوّله. وإن قُبل تظلّم من الإلغاء عاد الانتخاب إلى المرحلة التي أُلغي فيها، ما لم يُشغل المقعد بعده بانتخاب أو تعيين. وإن قُبل تظلّم من إعلان الفائز سقط الإعلان، وعاد من أُعلن إلى منصبه إن شغر، وإلا إلى ما يعود إليه المعزول (نظام الانضباط، المادة ٢١)، ثم يُعلن من توجبه المادتان ٢٦ و٢٧، أو يُعاد التصويت إن كان الخلل فيه."}]},{"no":32,"title":"الانتخابات السابقة","blocks":[{"kind":"para","text":"ما اكتمل أو أُلغي من الانتخابات قبل نفاذ الدستور باقٍ على حاله، ولا تظلّم منه (الدستور، المادة ٦٩). وما صدر في الانتخابات بين نفاذ الدستور ونفاذ هذا النظام فعلى ما في المادة ٢٤ من نظام الانضباط. وما كان قائمًا يوم نفاذ هذا النظام أُتمّ بأحكامه من المرحلة التي هو فيها، وتبدأ آجاله من يوم نفاذه."}]},{"no":33,"title":"النفاذ","blocks":[{"kind":"para","text":"يسري هذا النظام من تاريخ نشره في «أنظمة أدِيب» (الدستور، المادتان ٦٧ و٦٩)."}]}]}]$body$::jsonb
from public.regulations r where r.slug = 'elections'
on conflict (regulation_id, version_no) do nothing;

-- نظام الانضباط
insert into public.regulation_versions
  (regulation_id, version_no, status, effective_from, change_note, approval_note, body)
select r.id, 1, 'draft', null, 'الإصدار الأوّل', 'الإصدار الأول، أقرّه الرئيسان معًا بعد عرضه على المجلس الإداري في ١٢ أكتوبر ٢٠٢٦، ويسري من تاريخ نشره في «أنظمة أدِيب».',
  $body$[{"title":"الباب الأول: أحكام عامة","articles":[{"no":1,"title":"موضوع النظام","blocks":[{"kind":"para","text":"يفصّل هذا النظام الإنذار، وحدّ الإنذارات، وإلغاء الإنذار، والتظلّم من كل قرار يصدر بحقّ شخص بعينه. أمّا إنهاء العضوية وسماع العضو قبله ففي نظام العضوية. ويُقرأ مع الدستور ويُحيل إليه، وما خالفه منه لا يُعمل به (الدستور، المادتان ٣ و٦٥)."}]},{"no":2,"title":"التعريفات","blocks":[{"kind":"para","text":"يُراد بالألفاظ الآتية في هذا النظام ما بجانبها:"},{"kind":"list","ordered":false,"items":["**الإنذار:** قرار مكتوب يُسجَّل على عضو بعينه لمخالفة واجب، بتصنيف وسبب (الدستور، المادة ٥٦).","**الإنذار الساري:** إنذار لم يُلغَ.","**رتبة الإنذار:** ترتيبه الزمني بين الإنذارات السارية التي تُعدّ على صاحبه (المادة ١٣)، ويُعاد الترتيب إذا أُلغي إنذار. والعبرة بالسجلّ لا بالرتبة المذكورة في خطاب أُرسل من قبل.","**القرار:** كل ما يصدر بحقّ شخص بعينه بمقتضى الدستور أو أنظمة النادي، ومنه ما في المادة ٥٥ من الدستور."]}]},{"no":3,"title":"لا جزاء بلا نصّ","blocks":[{"kind":"para","text":"لا يُنذَر أحد إلا على مخالفة واجب منصوص عليه في الدستور أو أنظمة النادي (الدستور، المادة ٥٤)، ويُسمّى الواجب في الإنذار بتصنيفه (المادة ٦). ولا يُشترط الإنذار قبل إنهاء العضوية (الدستور، المادة ٤٠)."}]}]},{"title":"الباب الثاني: الإنذار","articles":[{"no":4,"title":"من يُصدره","blocks":[{"kind":"para","text":"يُصدر الإنذار من سمّتهم المادة ٥٦ من الدستور، كلٌّ في مداه من إنهاء العضوية (نظام العضوية، المادة ٢٢)، ومن كُلّف بمنصب أحدهم مدّة تكليفه. ولا يُصدره قائد إدارة الضمان والجودة ولا أعضاؤها، ولا أعضاء الإدارة التنفيذية، ولا حساب النادي المؤسّسي. ويُعدّ المنصب المجمَّد من مناصب صاحبه في المدى."}]},{"no":5,"title":"من لا يُنذَر","blocks":[{"kind":"para","text":"لا يُنذَر إلا عضو، ولا يُنذِر أحد نفسه، ولا يُنذَر أعضاء المجلس الإداري ومن كُلّف بمناصبهم (الدستور، المادتان ٥٦ و٥٩). ويشمل ذلك من جُمّد منصبه في المجلس ما دام مجمَّدًا (الدستور، المادتان ٢٦ و٣٢)، وقائد الإدارة التنفيذية إن عُيّن."}]},{"no":6,"title":"التصنيف","blocks":[{"kind":"para","text":"يُصنَّف كل إنذار في واحد من سبعة تصنيفات، لكلٍّ منها عبارته الثابتة في الخطاب، وما يكتبه المُصدر تفصيل لها. ولكل تصنيف الواجب الذي يُنذَر على مخالفته من المادة ٥١ من الدستور، وفي «مخالفة الدستور» و«أخرى» يُسمّي المُصدر المادة التي خولفت، من الدستور أو أنظمة النادي. وتُبدَّل عبارة «مخالفة سلوك» لأنها تُحيل إلى ما ليس في الدستور."},{"kind":"table","head":["التصنيف","عبارته في الخطاب","الواجب (الدستور، المادة ٥١)"],"rows":[["غياب","تكرّر غيابك عن الاجتماعات والأعمال ضمن مهامك","البند ١: الالتزام بالمهام"],["تأخّر","تكرّر التأخّر عن المواعيد المتّفق عليها","البند ١: الالتزام بالمهام"],["تقصير في مهمّة","عدم وجود تفاعل مع المهام المسندة إليك","البند ١: الالتزام بالمهام"],["انقطاع تواصل","انقطاع تواصلك داخل أدِيب","البند ٦: التجاوب مع القادة والإدارة"],["مخالفة سلوك","ما يخالف حسن التعامل مع إدارة النادي وأهله","البند ٤: حسن التعامل"],["مخالفة الدستور","مخالفة لدستور أدِيب","البنود ٢ و٣ و٥، وتُسمّى المادة"],["أخرى","ما يستوجب التنبيه","يُسمّى الواجب"]]}]},{"no":7,"title":"بيانات الإنذار","blocks":[{"kind":"para","text":"يُكتب للإنذار سبب يفصّل تصنيفه، ويُثبت فيه مُصدره، واللجنة، ومنصب المُنذَر يوم الإصدار (والأصيل مقدَّم على التكليف)، ولا تتغيّر بعد ذلك. وفي الغياب والتأخّر يذكر المُصدر في السبب تواريخ المرّات التي تكرّر فيها. ويُثبت فيه تاريخ الواقعة، ولا يكون في المستقبل ولا قبل انضمام العضو. ولا يُنذَر على واقعة إلا بما كان ساريًا يوم وقوعها (الدستور، المادة ٦٩)."}]},{"no":8,"title":"الواقعة","blocks":[{"kind":"para","text":"لا يصدر عن الواقعة الواحدة إلا إنذار واحد. ولا يُصدر الإنذار ولا يُلغيه من كان طرفًا في الواقعة، ويتولّاه غيره ممّن يبلغ صاحبها."}]},{"no":9,"title":"لا تعديل","blocks":[{"kind":"para","text":"لا يُعدَّل الإنذار بعد صدوره، وإنما يُلغى (المادة ١٥). ويُقيَّد في سجلّ النشاط كل إصدار، وكل إلغاء، وكل انتهاء عضوية بالحدّ."}]},{"no":10,"title":"التنبيه قبل الثالث","blocks":[{"kind":"para","text":"قبل تسجيل إنذار يبلغ به العضو الحدّ يُنبَّه المُصدر صراحةً إلى أنه يُنهي عضويته، ولا يمضي إلا بتأكيد ثانٍ."}]},{"no":11,"title":"الإبلاغ","blocks":[{"kind":"para","text":"لا يُشترط سماع العضو قبل إنذاره. ويُبلَّغ بالإنذار عند صدوره بإشعار في المنصّة، وبخطاب باسم إدارة الموارد البشرية فيه تصنيفه وسببه ورتبته، وما بقي له قبل الحدّ، وحقّه في التظلّم وأجله."}]},{"no":12,"title":"الاطّلاع","blocks":[{"kind":"para","text":"للعضو أن يطّلع على الإنذارات الصادرة بحقّه، ساريةً وملغاة، ومن أصدرها ومن ألغاها، ولو انتهت عضويته (الدستور، المادة ٥٠). ويُعرض له عدد سواريه وما بقي له قبل الحدّ. ويطّلع على سجلّ الإنذارات من يملك الإصدار، كلٌّ في مداه، ولا يطّلع عليه غيرهم."}]}]},{"title":"الباب الثالث: السريان والحدّ والإلغاء","articles":[{"no":13,"title":"السريان","blocks":[{"kind":"para","text":"لا يسقط الإنذار بمرور الزمن (الدستور، المادة ٥٧). ولا يُعدّ في الحدّ إلا ما صدر في العضوية القائمة: فإنذارات عضوية سابقة تبقى في السجلّ ولا تُعدّ على العضوية الجديدة (الدستور، المادة ٣٨)، ومن استُعيدت عضويته عادت معها إنذاراتها لأنها العضوية نفسها."}]},{"no":14,"title":"الحدّ","blocks":[{"kind":"para","text":"تنتهي العضوية بصدور الإنذار الثالث الساري، حكمًا من الدستور لا بسلطة المُصدر (الدستور، المادة ٥٧)، وفئتها ما في المادة ٢٦ من نظام العضوية، ويُعلَّم الإنذار الذي أوجبه. ويُكتب سبب الانتهاء «بلوغ حدّ الإنذارات (٣)»، ويُحال إلى الإنذارات في سجلّها، ولا يُنقل إليه سبب الإنذار الثالث. ولا يُسمع العضو قبل ذلك (الدستور، المادة ٤٠). وله أن يتظلّم من أيٍّ من الإنذارات التي بلغ بها الحدّ خلال أربعة عشر يومًا من إبلاغه بالانتهاء، ولو مضى أجل التظلّم منه."}]},{"no":15,"title":"الإلغاء","blocks":[{"kind":"para","text":"يُلغى الإنذار على ما في المادة ٥٧ من الدستور، والملغى يخرج من العدّ ويبقى في السجلّ مشطوبًا. ويبلغ العضوَ السابق في ذلك رئيسُ أدِيب، والرئيس التنفيذي، وقائد إدارة الموارد البشرية. ويجب إلغاؤه إذا ثبت خطؤه، أو ظهر لصاحبه عذر ينفي المخالفة، أو قُبل التظلّم منه، ولا يمنع ذلك إلغاءه لغير ذلك بقرار مسبَّب. ويُبلَّغ صاحبه بالإلغاء."}]},{"no":16,"title":"الإلغاء بعد انتهاء العضوية","blocks":[{"kind":"para","text":"إلغاء الإنذار الذي انتهت به العضوية لا يعيدها، وإنما تُستعاد على ما في نظام العضوية (المادتان ٣٠ و٣١)، فإن أُلغي بقبول التظلّم منه استُعيدت (الدستور، المادة ٥٨). ولا تُستعاد عضوية انتهت بالحدّ حتى يُلغى من إنذاراتها ما ثبت خطؤه، فلا تعود وعليها ثلاثة إنذارات سارية."}]}]},{"title":"الباب الرابع: التظلّم","articles":[{"no":17,"title":"ما يُتظلَّم منه","blocks":[{"kind":"para","text":"لمن صدر بحقّه قرار أن يتظلّم منه (الدستور، المادة ٥٨)، ومن ذلك: الإنذار، وإنهاء العضوية، والنقل إلى المتطوّعين، وتأجيل طلب الخروج، والعزل من المنصب، والحرمان من الترشّح، ورفض طلب التطوّع، وإنهاء التطوّع، وحجب الشهادة وإبطالها. وما يتّصل بالانتخابات فعلى ما في نظام الانتخابات من أجل وأثر. ولا يُتظلَّم من قرار صدر بطلب صاحبه، ولا من قرار البتّ في تظلّم."}]},{"no":18,"title":"تقديمه","blocks":[{"kind":"para","text":"يُقدَّم التظلّم كتابةً بسببه في منصّة أدِيب، أو إلى من يبتّ فيه بأي وسيلة مكتوبة ما دام لا باب له فيها، خلال أربعة عشر يومًا من إبلاغ صاحبه بالقرار، فإن لم يُبلَّغ فمن اطّلاعه عليه. ولا يكون للقرار الواحد إلا تظلّم واحد."}]},{"no":19,"title":"من يبتّ فيه","blocks":[{"kind":"para","text":"يبتّ في التظلّم من يقابل مُصدر القرار في هذا الجدول (الدستور، المادة ٥٨):"},{"kind":"table","head":["القرار","يبتّ في التظلّم منه"],"rows":[["من رئيس أدِيب بحقّ الرئيس التنفيذي، أو من الرئيس التنفيذي بموافقة رئيس أدِيب","رئيس أدِيب، وهو المرجع الأخير"],["من رئيس أدِيب في غير ذلك","الرئيس التنفيذي"],["من الرئيس التنفيذي في غير ذلك","رئيس أدِيب"],["من غيرهما","الرئيسان معًا، ولا يُقبل إلا باتّفاقهما"]]},{"kind":"para","text":"ولا يبتّ في التظلّم من منعته المادة ٥٨ من الدستور. ويأخذ المكلَّف بمنصب الرئيس التنفيذي حكمه في الجدول، وما أصدره الرئيس التنفيذي وهو قائم مقام رئيس أدِيب فهو من قراره، وما صدر من حساب النادي المؤسّسي فهو من غيرهما. وما يبتّ فيه الرئيسان معًا يُرجأ في غياب رئيس أدِيب إلى عودته، ولا تُحسب مدّة الغياب من أجل البتّ (الدستور، المادة ٢٨). وما صدر من الرئيسين معًا فلا تظلّم منه."}]},{"no":20,"title":"البتّ","blocks":[{"kind":"para","text":"يُبتّ في التظلّم خلال أربعة عشر يومًا من تقديمه، بقرار مكتوب مسبَّب يُبلَّغ به صاحبه ومُصدر القرار، ولمن يبتّ فيه أن يسمعهما. وقرار البتّ نهائي. وإن لم يتّفق الرئيسان فيما يبتّان فيه معًا عُدّ مرفوضًا. وإن مضت المدّة ولم يُبتّ فيه عُدّ مرفوضًا، ودُوِّن ذلك."}]},{"no":21,"title":"أثره","blocks":[{"kind":"para","text":"لا يوقف التظلّم القرار. فإن قُبل أُلغي القرار، واستُعيدت العضوية إن كان إنهاءً لها أو إنذارًا من الإنذارات التي انتهت بها (الدستور، المادة ٥٨؛ ونظام العضوية، المادتان ٣٠ و٣١). ويُجري الاستعادة أحدُ من بتّ فيه. وإن كان تأجيلًا لطلب الخروج انتهت العضوية يوم القبول (نظام العضوية، المادة ١٩). وإن كان عزلًا أُعيد صاحبه إلى منصبه إن شغر، وإلا إلى ما يعود إليه المعزول (الدستور، المادة ٢٥). وما سوى ذلك يُعاد إلى حاله قبل القرار."}]},{"no":22,"title":"السجلّ","blocks":[{"kind":"para","text":"يُقيَّد كل تظلّم وقرار البتّ فيه في سجلّ النادي، ويطّلع عليه صاحبه ومن بتّ فيه ومُصدر القرار."}]}]},{"title":"الباب الخامس: أحكام ختامية","articles":[{"no":23,"title":"الإنذارات السابقة","blocks":[{"kind":"para","text":"تبقى الإنذارات الصادرة في منصّة أدِيب قبل نفاذ الدستور سارية، وتُعدّ في الحدّ. ولا تُعدّ فيه إنذارات سُجّلت خارج المنصّة، وتُحفظ في سجلّ النادي إن رُحّلت إليه."}]},{"no":24,"title":"القرارات السابقة","blocks":[{"kind":"para","text":"لا تظلّم ممّا صدر قبل نفاذ الدستور (الدستور، المادة ٦٩). وما صدر بين نفاذ الدستور ونفاذ هذا النظام يُتظلَّم منه خلال ثلاثين يومًا من نفاذه."}]},{"no":25,"title":"النفاذ","blocks":[{"kind":"para","text":"يسري هذا النظام من تاريخ نشره في «أنظمة أدِيب» (الدستور، المادتان ٦٧ و٦٩)."}]}]}]$body$::jsonb
from public.regulations r where r.slug = 'discipline'
on conflict (regulation_id, version_no) do nothing;

-- نظام التطوّع
insert into public.regulation_versions
  (regulation_id, version_no, status, effective_from, change_note, approval_note, body)
select r.id, 1, 'draft', null, 'الإصدار الأوّل', 'الإصدار الأول، أقرّه الرئيسان معًا بعد عرضه على المجلس الإداري في ١٢ أكتوبر ٢٠٢٦، ويسري من تاريخ نشره في «أنظمة أدِيب».',
  $body$[{"title":"الباب الأول: أحكام عامة","articles":[{"no":1,"title":"موضوع النظام","blocks":[{"kind":"para","text":"يفصّل هذا النظام المواد ٦ و٥٢ و٥٩ إلى ٦١ من الدستور: صفة المتطوّع وثبوتها وانتهاؤها، والرغبات، وفرص التطوّع، والتقديم إليها والقبول والرفض والاعتذار، والحضور والساعات، وسجلّ المتطوّعين. ويُقرأ مع الدستور ويُحيل إليه، وما خالفه منه لا يُعمل به (الدستور، المادتان ٣ و٦٥)."}]},{"no":2,"title":"التعريفات","blocks":[{"kind":"para","text":"يُراد بالألفاظ الآتية في هذا النظام ما بجانبها:"},{"kind":"list","ordered":false,"items":["**المتطوّع:** من له تطوّع قائم وليست له عضوية (الدستور، المادة ٦).","**مدير التطوّع:** من يملك إدارة التطوّع: رئيس أدِيب، والرئيس التنفيذي، وقائد إدارة الموارد البشرية، وأعضاؤها، ومن كُلّف بمناصبهم، وحساب النادي المؤسّسي فيما يُسنده إليه رئيس أدِيب (الدستور، المادتان ٣٤ و٦١؛ ونظام المناصب والصلاحيات، المادة ١٩).","**الفرصة:** عمل تطوّعي يفتحه مدير التطوّع ويتقدّم إليه المتطوّعون.","**الفترة:** يوم من أيّام الفرصة له ساعة بدء وساعة انتهاء، وقد تكون له مقاعد. وتكون للفرصة فترة أو أكثر، أو لا تكون لها فترات.","**الفرصة المرنة:** فرصة بلا فترات ولا أيّام محدّدة، قد يكون لها آخر يوم، وتنتهي به أو بإنهاء مدير التطوّع إيّاها.","**الطلب:** تقدّم المتطوّع إلى فرصة أو إلى فترة منها، وهو «طلب التطوّع» في المادتين ٥٥ و٦١ من الدستور.","**الموعد:** الفترة التي تقدّم إليها المتطوّع، أو أيّام الفرصة إن لم تكن لها فترات، ويبدأ بساعة بدئه أو بأوّل يوم فيه، وينقضي بآخر ساعة فيه. وموعد الفرصة المرنة من فتحها إلى انتهائها."]}]},{"no":3,"title":"إدارة التطوّع","blocks":[{"kind":"para","text":"يملك كل مدير تطوّع منفردًا فتحَ الفرص وتعديلها وإغلاقها، والبتَّ في الطلبات، وتسجيل الحضور، وإنهاء التطوّع، ولا يملكه غيره (الدستور، المادتان ٦١ و٦٦). ولقائد اللجنة التي طلبت الفرصة ونائبه أن يرفعا إلى مدير التطوّع ما يريانه في حضور المتطوّعين وتميّزهم، والقرار له."}]}]},{"title":"الباب الثاني: المتطوّع","articles":[{"no":4,"title":"من يتطوّع","blocks":[{"kind":"para","text":"لكل صاحب حساب استكمل ملفّه وليس عضوًا أن يتطوّع، ومنه العضو السابق (الدستور، المادة ٦٠). واستكمال الملف: الاسم بالعربية، والجنس، ورقم الجوال. ولا يُشترط للتطوّع سنّ ولا دراسة ولا عمل (الدستور، المادة ٩)."}]},{"no":5,"title":"من أُنهيت عضويته لمخالفة","blocks":[{"kind":"para","text":"من أُنهيت آخر عضوية له في فئة «المخالفة أو الإساءة»، ومنه بلوغ حدّ الإنذارات في هذه الفئة، لا يتطوّع إلا بإذن أحد الرئيسين (الدستور، المادتان ١٠ و٦٠؛ ونظام العضوية، المواد ١١ و٢٣ و٢٦). فيبقى تقدّمه معلّقًا حتى يأذن له أحدهما، أو يرفضه بسبب مكتوب يطّلع عليه ويتظلّم منه (الدستور، المادتان ٥٥ و٥٨). ومن أُذن له ثم انتهى تطوّعه لم يعد إلا بإذن جديد."}]},{"no":6,"title":"ثبوت الصفة","blocks":[{"kind":"para","text":"يصير صاحب الحساب متطوّعًا بتقدّمه إلى التطوّع وترتيبه رغباته، بلا مراجعة ولا قبول (الدستور، المادة ٦)، ويُعرض عليه بعدها رابط مجموعة متطوّعي أدِيب ليدخلها. ويصير العضو متطوّعًا كذلك بنقله إلى المتطوّعين (نظام العضوية، المادة ٢٧)."}]},{"no":7,"title":"الرغبات","blocks":[{"kind":"para","text":"يرتّب المتطوّع ثلاث رغبات في ثلاث لجان مختلفة من لجان المجلس التشغيلي، أو في ما عُرض منها إن كان أقلّ، وله أن يعيد ترتيبها ما دام متطوّعًا. ولا تُعرض للرغبات إلا لجنة قائمة لها تعريف مكتوب، ولا تُعرض إدارة من إدارات المجلس الإداري (الدستور، المادة ٦٠). ومن صار متطوّعًا بالنقل، أو سقطت لجنة من رغباته بإلغائها أو بانقطاع عرضها، رتّب رغباته قبل أن يتقدّم إلى فرصة."}]},{"no":8,"title":"انتهاء التطوّع","blocks":[{"kind":"para","text":"ينتهي التطوّع بأحد أربعة:"},{"kind":"list","ordered":true,"items":["الإهداء، بسبب «نال العضوية» (نظام العضوية، المادة ٨).","استعادة العضوية (نظام العضوية، المادة ٣١).","إنهاء مدير التطوّع إيّاه (المادة ٩).","ترك المتطوّع التطوّع بإرادته متى شاء، فيصير صديقًا لأدِيب (الدستور، المادة ٧)."]},{"kind":"para","text":"وبانتهائه تُلغى طلباته المعلّقة. فإن انتهى بالإنهاء أو الترك أُلغي قبوله فيما لم يبدأ موعده وفي الفرص المرنة القائمة، وإن انتهى بالإهداء أو الاستعادة بقي قبوله، فيحضر ويأخذ شهادته."}]},{"no":9,"title":"إنهاء التطوّع","blocks":[{"kind":"para","text":"لا يُنذَر المتطوّع، وإنما يُنهي مدير التطوّع تطوّعه بقرار مكتوب بسببه (الدستور، المادتان ٥٩ و٦١). ويطّلع صاحبه على السبب، وله أن يتظلّم منه (الدستور، المادتان ٥٥ و٥٨؛ ونظام الانضباط، الباب الرابع). ولا يُنهى إلا لأحد أمرين: إخلاله بواجب من واجباته في المادة ٥٢ من الدستور يُسمّى في القرار، وهي الالتزام بما قُبل فيه من فرص، وحسن التعامل مع النادي وأهله، وصون معلوماته، ومن الإخلال بالالتزام أن يغيب عمّا قُبل فيه مرّتين بلا عذر يقبله مدير التطوّع؛ أو انقطاعه، بألّا يتقدّم إلى فرصة ستة أشهر متّصلة فُتحت فيها فرص يحقّ له التقدّم إليها. ويُبلَّغ بالإنهاء."}]},{"no":10,"title":"العودة","blocks":[{"kind":"para","text":"من انتهى تطوّعه عاد متطوّعًا بتقدّمه من جديد وترتيبه رغباته، ويبقى له تاريخ أوّل تقديم، ويُحفظ سجلّ تطوّعه السابق وسبب انتهائه. ومن عاد بعد أن أنهى مدير التطوّع تطوّعه، فلمدير التطوّع أن يرفض طلباته بسبب يُحيل إلى قرار الإنهاء (المادة ١٨)."}]}]},{"title":"الباب الثالث: الفرص","articles":[{"no":11,"title":"فتح الفرصة","blocks":[{"kind":"para","text":"يفتح مدير التطوّع الفرصة بعنوان ووصف، وله أن يحدّد فيها اللجنة الطالبة، والمكان، وعدد المقاعد، وأيّامها وساعاتها، أو يجعلها مرنة. ويجوز قصرها على الذكور أو الإناث، ويُحتكم فيه إلى الجنس المسجّل في ملف المتطوّع. ولا تُفتح فرصة لها أيّام إلا بساعاتها، وما كان منها لأكثر من يوم جُعل فترات."}]},{"no":12,"title":"حالات الفرصة","blocks":[{"kind":"para","text":"تكون الفرصة مسوّدة لا يراها المتطوّعون، أو مفتوحة تقبل التقديم، أو مغلقة لا تقبله، وإغلاقها لا يمسّ ما قُبل فيها. ويغلقها مدير التطوّع متى شاء، وتُغلق وحدها إذا امتلأت مقاعدها أو انقضى آخر موعد فيها، وتُفتح وحدها إذا خلا مقعد في الممتلئة. والفرصة المرنة تنتهي بآخر يوم فيها إن كان لها، أو بإنهاء مدير التطوّع إيّاها. وتُعلَن الفرصة برابطها في مجموعة المتطوّعين، والمرجع ما في المنصّة."}]},{"no":13,"title":"تعديل الفرصة","blocks":[{"kind":"para","text":"لمدير التطوّع أن يعدّل الفرصة بعد القبول فيها، فلا ينزل بالمقاعد عمّا قُبل، ولا يحذف فترة لها طلبات، ولا يجعل بدء موعد في الماضي. ولا يقصرها على جنس بعد قبول من يخالفه. وإذا غيّر يوم فترة أو ساعتها بُلّغ المقبولون فيها، ولمن لا يناسبه الموعد الجديد أن يعتذر قبل بدئه (المادة ١٩)."}]},{"no":14,"title":"إلغاء الفرصة","blocks":[{"kind":"para","text":"لمدير التطوّع أن يُلغي فرصة لم يبدأ أوّل موعد فيها، بقرار مكتوب بسببه يُبلَّغ به المتقدّمون إليها، فتُلغى طلباتها كلّها وتبقى في السجلّ. ولا تُحذف فرصة لها طلبات."}]}]},{"title":"الباب الرابع: التقديم والقبول والاعتذار","articles":[{"no":15,"title":"التقديم","blocks":[{"kind":"para","text":"لا يتقدّم إلى الفرصة إلا متطوّع، ومن كان صديقًا لأدِيب عُرض عليه التطوّع أوّلًا (الدستور، المادة ٥٢). ويتقدّم إلى الفرصة المفتوحة ما لم ينقضِ موعدها ووافقه قصرها على جنس، مرّة واحدة للفرصة أو لكل فترة منها، ولا يحجز التقديم مقعدًا. ولمن سحب طلبه أو اعتذر أو انتهى طلبه دون بتّ أن يتقدّم من جديد، ولا يتقدّم من رُفض طلبه إلى ما رُفض فيه."}]},{"no":16,"title":"السحب","blocks":[{"kind":"para","text":"للمتطوّع أن يسحب طلبه ما لم يُبتّ فيه (الدستور، المادة ٥٢)."}]},{"no":17,"title":"القبول","blocks":[{"kind":"para","text":"يقبل مدير التطوّع الطلب، ولا يقبل فوق المقاعد، وله أن يقبل ما لم ينقضِ موعد الطلب (الدستور، المادة ٦١). فإن انقضى ولم يُبتّ فيه انتهى بـ«انتهى الموعد قبل المراجعة»، ولا يُعدّ ذلك رفضًا، ومنه الطلب المعلّق في فرصة مرنة انتهت. ولا يقبل إلا من كان متطوّعًا يوم القبول ووافقه قصر الفرصة على جنس. وإذا زاد المتقدّمون على المقاعد فاضل بينهم بتقديره، مستأنسًا برغباتهم وأسبقيّة تقديمهم."}]},{"no":18,"title":"الرفض","blocks":[{"kind":"para","text":"لا يُرفض طلب إلا بقرار مكتوب بسببه يطّلع عليه صاحبه (الدستور، المادتان ٥٥ و٦١). وله أن يتظلّم منه (الدستور، المادة ٥٨؛ ونظام الانضباط، الباب الرابع). فإن قُبل التظلّم بعد انقضاء الموعد صُحّح السجلّ، ولم يُعَد الطلب."}]},{"no":19,"title":"الاعتذار","blocks":[{"kind":"para","text":"للمقبول أن يعتذر بسبب مكتوب ما لم يبدأ موعده، وفي الفرصة المرنة ما لم تنتهِ، فيخلو مقعده (الدستور، المادة ٥٢). ومن غاب عمّا قُبل فيه دون اعتذار سُجّل غائبًا."}]},{"no":20,"title":"إلغاء القبول","blocks":[{"kind":"para","text":"لمدير التطوّع أن يُلغي قبول متطوّع ما لم يبدأ موعده، وفي الفرصة المرنة ما لم تنتهِ، بقرار مكتوب بسببه يُبلَّغ به ويُتظلَّم منه كالرفض، فيخلو مقعده. ويُلغى القبول كذلك بما في المادتين ٨ و١٤. ويُعلَّم الطلب في ذلك كلّه «أُلغي». ولا يتقدّم من أُلغي قبوله بقرار إلى ما أُلغي فيه، ولغيره أن يتقدّم من جديد."}]}]},{"title":"الباب الخامس: الحضور والساعات","articles":[{"no":21,"title":"الحضور","blocks":[{"kind":"para","text":"يسجّل مدير التطوّع حضور المقبولين، «حاضرًا» أو «غائبًا»، لكل فترة، أو مرّة واحدة للفرصة إن لم تكن لها فترات، ولا يسجّله قبل بدء الموعد (الدستور، المادة ٦١). وله أن يُثبت مشاركة متطوّع، قائم أو سابق، شارك في فرصة دون أن يتقدّم إليها، بسبب مكتوب، فيُعدّ مقبولًا حاضرًا. وله أن يصحّح الحضور ما لم تصدر الشهادة، فإن صدرت لم يُصحَّح إلا بإبطالها (الدستور، المادة ٦٤؛ ونظام الشهادات)."}]},{"no":22,"title":"الساعات","blocks":[{"kind":"para","text":"تحسب المنصّة ساعات تطوّع الحاضر: في الفرصة ذات الفترات مجموع ساعات ما حضره منها، وفي الفرصة ذات الأيّام بلا فترات ساعات اليوم في عدد أيّامها. ولا تُكتب الساعات بيد إلا في الفرصة المرنة، فيكتب مدير التطوّع ساعات كل حاضر عند تسجيل حضوره."}]},{"no":23,"title":"الملاحظة الإدارية","blocks":[{"kind":"para","text":"لمدير التطوّع أن يكتب على المقبول ملاحظة إدارية لا يطّلع عليها المتطوّع. ولا تكون عقوبة، ولا يُبنى عليها قرار بحقّه لم يُذكر سببه فيه، وما استحقّ المساءلة فطريقه المادة ٩."}]},{"no":24,"title":"شهادة المشاركة","blocks":[{"kind":"para","text":"لكل من قُبل في فرصة وحضرها شهادة مشاركة بساعاته ما لم تُحجب، ولا شهادة لغائب، ويُرشَّح المتميّز بجملة تُطبع فيها، على ما في المادة ٦٢ من الدستور ونظام الشهادات."}]}]},{"title":"الباب السادس: السجلّ والتبليغ وأحكام ختامية","articles":[{"no":25,"title":"سجلّ المتطوّعين","blocks":[{"kind":"para","text":"يطّلع مدير التطوّع على سجلّ المتطوّعين القائمين والسابقين: الاسم، والجوال، والبريد، والجنس، والمدينة، والرغبات، والطلبات وما صدر فيها، والحضور، والملاحظات الإدارية، وأسباب انتهاء التطوّع. ويطّلع المتطوّع على طلباته وما صدر فيها، ومنه سبب رفضها. ويطّلع على سبب إنهاء تطوّعه ولو صار سابقًا (الدستور، المادة ٥٥). ويبقى للمتطوّع السابق الاطّلاع على سجلّ تطوّعه."}]},{"no":26,"title":"التبليغ والقيد","blocks":[{"kind":"para","text":"يُبلَّغ المتطوّع في المنصّة بقبول طلبه ورفضه، وإلغاء قبوله، وتغيير موعده، وإلغاء الفرصة، وإنهاء تطوّعه. ويُقيَّد في سجلّ النشاط بفاعله ويومه: فتح الفرصة وتعديلها وإغلاقها وإلغاؤها، والقبول والرفض وإلغاء القبول، والسحب والاعتذار، والحضور، والإذن بالتطوّع، وترك التطوّع وإنهاؤه."}]},{"no":27,"title":"القائم يوم النفاذ","blocks":[{"kind":"para","text":"يبقى المتطوّعون والفرص والطلبات القائمة يوم نفاذ هذا النظام على حالها، ويجري عليها حكمه من يومه، ومنه ترتيب الرغبات في المادة ٧."}]},{"no":28,"title":"النفاذ","blocks":[{"kind":"para","text":"يسري هذا النظام من تاريخ نشره في «أنظمة أدِيب» (الدستور، المادتان ٦٧ و٦٩)."}]}]}]$body$::jsonb
from public.regulations r where r.slug = 'volunteering'
on conflict (regulation_id, version_no) do nothing;

-- نظام الشهادات
insert into public.regulation_versions
  (regulation_id, version_no, status, effective_from, change_note, approval_note, body)
select r.id, 1, 'draft', null, 'الإصدار الأوّل', 'الإصدار الأول، أقرّه الرئيسان معًا بعد عرضه على المجلس الإداري في ١٢ أكتوبر ٢٠٢٦، ويسري من تاريخ نشره في «أنظمة أدِيب».',
  $body$[{"title":"الباب الأول: أحكام عامة","articles":[{"no":1,"title":"موضوع النظام","blocks":[{"kind":"para","text":"يفصّل هذا النظام المواد ٦٢ إلى ٦٤ من الدستور: شهادة الخبرة وشهادة المشاركة، وإصدارهما ومضمونهما، والرقم والتحقّق، والحجب والتميّز، والإبطال (الدستور، المادة ٦٥). ويُقرأ مع الدستور ويُحيل إليه، وما خالفه منه لا يُعمل به (الدستور، المادة ٣)."}]},{"no":2,"title":"التعريفات","blocks":[{"kind":"para","text":"يُراد بالألفاظ الآتية في هذا النظام ما بجانبها:"},{"kind":"list","ordered":false,"items":["**شهادة الخبرة:** وثيقة تُثبت لعضو؍ حاليّ أو سابق اسمه ومسمّاه وفترة عضويته (الدستور، المادة ٦٣).","**شهادة المشاركة:** وثيقة تُثبت لمن قُبل في فرصة تطوّع وحضرها مشاركته وساعات تطوّعه فيها (الدستور، المادة ٦٢).","**المُصدر:** من يملك إصدار الشهادة لصاحبها، وهو من يملك إبطالها (الدستور، المادة ٦٤).","**مدير التطوّع:** من يملك إدارة التطوّع على ما في المادة ٢ من نظام التطوّع.","**الرقم:** الرقم المرجعي الفريد الذي تُعرف به الشهادة ويُتحقّق منها به."]}]},{"no":3,"title":"حجّية الشهادة","blocks":[{"kind":"para","text":"الشهادة إثبات لواقع مسجّل في المنصّة، لا حكم على صاحبها ولا تزكية له، ويبقى مضمونها كما كان يوم إصدارها فلا يتغيّر بانتقال صاحبها أو انتهاء عضويته أو إغلاق الفرصة أو إلغاء اللجنة، إلا اسم صاحبها إذا صحّحه (الدستور، المادة ٦٤)."}]}]},{"title":"الباب الثاني: شهادة الخبرة","articles":[{"no":4,"title":"من يُصدرها","blocks":[{"kind":"para","text":"يُصدر شهادة الخبرة ويُبطلها رئيس أدِيب لكل أحد، والرئيس التنفيذي لكل أحد إلا رئيس أدِيب، وقائد إدارة الموارد البشرية لكل أحد إلا الرئيسين وقائد الضمان والجودة، ومن كُلّف بمناصبهم (الدستور، المادتان ٣٤ و٦٣). ويُعتبر في ذلك ما عليه صاحب الشهادة يوم الإصدار أو الإبطال، ويُعدّ المكلَّف بمنصب كصاحبه، ويملك الثلاثة إصدارها للعضو السابق. ولا يُصدرها أحد لنفسه إلا رئيس أدِيب (الدستور، المادة ٦٣). ولا يُصدرها حساب النادي المؤسّسي (نظام المناصب والصلاحيات، المادة ١٩)."}]},{"no":5,"title":"لمن تُصدر","blocks":[{"kind":"para","text":"تُصدر شهادة الخبرة لعضو حاليّ أو سابق له تاريخ انضمام، بتقدير من يملك إصدارها، ولا تُشترط لها مدّة."}]},{"no":6,"title":"الاسم والمسمّى","blocks":[{"kind":"para","text":"يُثبت في الشهادة اسم صاحبها الثلاثي من سجلّ عضويته، وإلا اسمه في ملفّه، وللمُصدر أن يصحّحه قبل الإصدار. ويُثبت مسمّاه: مناصبه القائمة كلّها مجموعةً ومنها المجمَّد، وما كان منها تكليفًا وُصف به، ومن لا منصب له قائم فآخر منصب أصيل شغله. ويؤنَّث المسمّى للمرأة (الدستور، المادة ٨). وللمُصدر أن يصحّح المسمّى قبل الإصدار، ولا يكتب فيه إلا منصبًا شغله صاحبه، وما لم يعد يشغله وُصف بـ«سابقًا»."}]},{"no":7,"title":"الفترة","blocks":[{"kind":"para","text":"تبدأ الفترة بتاريخ انضمام العضوية، ومن استُعيدت عضويته فمن تاريخها الأوّل (الدستور، المادة ٤٣)، وتنتهي يوم الإصدار للعضو الحالي. وتنتهي للعضو السابق يوم انتهاء عضويته. ومن تعدّدت عضوياته أُثبتت له الأخيرة، ويجوز أن تُصدر له شهادة لكل عضوية سابقة بفترتها في سجلّ النادي، ومسمّاه فيها آخر منصب أصيل شغله (نظام العضوية، المادة ١١)."}]},{"no":8,"title":"تعدّد الشهادات","blocks":[{"kind":"para","text":"يجوز أن تُصدر لصاحب الشهادة شهادة أخرى، وتبقى السابقة سارية بما فيها يوم إصدارها، ويُنبَّه المُصدر قبل الإصدار بما سبقها."}]}]},{"title":"الباب الثالث: شهادة المشاركة، وأرقام الفعاليات","articles":[{"no":9,"title":"استحقاق شهادة المشاركة","blocks":[{"kind":"para","text":"لكل من قُبل في فرصة وحضرها شهادة مشاركة بساعات ما حضر ما لم تُحجب، ولا شهادة لغائب، وله في الفرصة الواحدة شهادة واحدة سارية. وفي الفرصة ذات الفترات لا تصدر حتى يُسجَّل حضوره أو غيابه في كل فترة قُبل فيها (الدستور، المادة ٦٢؛ ونظام التطوّع، المواد ٢١ إلى ٢٤). والغياب ليس حجبًا، فلا يُكتب للغائب سبب حجب."}]},{"no":10,"title":"إصدارها ومضمونها","blocks":[{"kind":"para","text":"يُصدر شهادة المشاركة مدير التطوّع، فرادى أو جملة، ولا تصدر آليًّا. وتُثبت اسم صاحبها في ملفّه، وعنوان الفرصة، واللجنة الطالبة إن حُدّدت، وتاريخَي المشاركة، وساعاته، وجملة تميّزه إن رُشّح. وتصدر كذلك لمن أُثبتت مشاركته دون طلب (الدستور، المادة ٦٢؛ ونظام التطوّع، المادة ٢١). وتصدر خلال أربعة عشر يومًا من اكتمال حضوره ما لم تُحجب."}]},{"no":11,"title":"التميّز","blocks":[{"kind":"para","text":"يرشّح مدير التطوّع المتميّز قبل إصدار شهادته بجملة لا تزيد على ثلاثمئة حرف تُطبع فيها مع ختم «بتميّز»، وله رفع الترشيح قبل الإصدار، ولا يُرشَّح محجوب، ويسقط الترشيح بالحجب. ولقائد اللجنة الطالبة ونائبه أن يرفعا إليه رأيهما (الدستور، المادة ٦٢؛ ونظام التطوّع، المادة ٣). فإن صدرت الشهادة لم يُضَف إليها التميّز ولم يُرفع منها."}]},{"no":12,"title":"الحجب","blocks":[{"kind":"para","text":"الحجب استثناء، ولا يكون إلا لمخالفة صريحة، ولصاحبها أن يتظلّم منه (الدستور، المادتان ٥٨ و٦٢؛ ونظام الانضباط، الباب الرابع). ويحجبها مدير التطوّع قبل إصدارها بسبب مكتوب يطّلع عليه صاحبها، ويرفع الحجب متى رأى، وما صدر لا يُحجب بل يُبطَل على ما في المادة ١٧. والمخالفة الصريحة إخلال صاحبها في الفرصة نفسها بواجب من واجباته في المادة ٥١ أو ٥٢ من الدستور، يُسمّى في القرار."}]},{"no":13,"title":"أرقام حضور الفعاليات","blocks":[{"kind":"para","text":"ما يُنشأ من أرقام عند تسجيل حضور الفعاليات ليس شهادة في هذا النظام، ولا يُسمّى شهادة حتى ينظّمه تعديل له تجري فيه عليه المادة ٦٤ من الدستور. ولا تُعطى بيانات صاحب الحجز لمن يطلبها برقمه."}]}]},{"title":"الباب الرابع: الرقم والتحقّق والإبطال","articles":[{"no":14,"title":"الرقم","blocks":[{"kind":"para","text":"لكل شهادة رقم مرجعي فريد لا يُخمَّن، يُطبع عليها مع رمز يقود إلى صفحة التحقّق، ولا يتغيّر بتغيّر اسم صاحبها. ويميّز الرقم نوع الشهادة: «ADEEB-EXP» للخبرة، و«ADEEB-VOL» للمشاركة."}]},{"no":15,"title":"التحقّق","blocks":[{"kind":"para","text":"يتحقّق أي أحد من الشهادة برقمها وحده في صفحة التحقّق بلا حساب (الدستور، المادة ٦٤)، فيُجاب بأنها سارية أو مُبطَلة أو غير موجودة، ويرى نوعها، واسم صاحبها وأسماءه السابقة، ومسمّاه أو فرصته، وفترتها، وساعاتها وتميّزها، ويوم إصدارها أو إبطالها. ولا يُبحث فيها بالاسم، ولا تُعرض قائمة الشهادات، ولا يُعرض المُصدر ولا سبب الإبطال."}]},{"no":16,"title":"الاسم بعد الإصدار","blocks":[{"kind":"para","text":"تظهر الشهادة باسم صاحبها الحالي إذا صحّحه، ويبقى رقمها، ويُحفظ اسمه يوم إصدارها، وتذكر صفحة التحقّق أسماءه السابقة بتواريخها (الدستور، المادة ٦٤). ولا يتغيّر اسمها إلا بتصحيح الاسم الذي صدرت به، فلا يحلّ اسم ملفّه محلّ اسمه الثلاثي."}]},{"no":17,"title":"الإبطال","blocks":[{"kind":"para","text":"تُبطَل الشهادة بقرار مكتوب بسببه ممّن يملك إصدارها، وتبقى في السجلّ مشطوبة برقمها، ويُجاب المتحقّق بأنها مُبطَلة (الدستور، المادة ٦٤). ويطّلع صاحبها على سبب الإبطال، وله أن يتظلّم منه (الدستور، المادتان ٥٥ و٥٨). وإذا أُعيد إصدارها صدرت برقم جديد، وبقيت المُبطَلة في السجلّ. ولا تُبطَل إلا لخطأ في إصدارها أو في مضمونها يوم الإصدار، ومنه ما أُلغي بأثر رجعي باستعادة العضوية أو بقبول تظلّم، لا لما يطرأ بعده."}]}]},{"title":"الباب الخامس: الاطّلاع والسجلّ وأحكام ختامية","articles":[{"no":18,"title":"الاطّلاع","blocks":[{"kind":"para","text":"لصاحب الشهادة أن يطّلع على شهاداته السارية وينزّلها دون مراجعة أحد، ويطّلع على شهادة الخبرة من يملك إصدارها لصاحبها، وعلى شهادة المشاركة مدير التطوّع. ويرى صاحبها المُبطَلة منها مشطوبة بسبب إبطالها (الدستور، المادة ٥٥). ويبقى له ذلك كلّه ولو انتهت عضويته أو تطوّعه."}]},{"no":19,"title":"الورقة","blocks":[{"kind":"para","text":"تُرسم ورقة الشهادة عند كل تنزيل من قالبها القائم بجنس صاحبها، وعليها رقمها ورمز التحقّق."}]},{"no":20,"title":"القيد والتبليغ","blocks":[{"kind":"para","text":"يُقيَّد في سجلّ النشاط بفاعله ويومه كل إصدار وإبطال وحجب ورفع حجب وترشيح للتميّز. ويُبلَّغ صاحب الشهادة في المنصّة بإصدارها وحجبها وإبطالها."}]},{"no":21,"title":"القائم يوم النفاذ","blocks":[{"kind":"para","text":"تبقى الشهادات الصادرة قبل نفاذ هذا النظام سارية بأرقامها ومضمونها، ويجري عليها حكمه من يومه."}]},{"no":22,"title":"النفاذ","blocks":[{"kind":"para","text":"يسري هذا النظام من تاريخ نشره في «أنظمة أدِيب» (الدستور، المادتان ٦٧ و٦٩)."}]}]}]$body$::jsonb
from public.regulations r where r.slug = 'certificates'
on conflict (regulation_id, version_no) do nothing;

-- حارسٌ: سبعُ مسودّاتٍ للإصدار الأوّل، وعددُ الموادّ كما في النصوص.
do $chk$
declare n int;
begin
  select count(*) into n from public.regulation_versions where version_no = 1;
  if n <> 7 then raise exception 'النسخ % لا ٧', n; end if;
  select sum(jsonb_array_length(a)) into n from public.regulation_versions v,
    lateral (select ch->'articles' as a from jsonb_array_elements(v.body) ch) x where v.version_no = 1;
  if n <> 236 then raise exception 'الموادّ % لا 236', n; end if;
end $chk$;

commit;
